/** dsh-notifier channels 域 —— 各出口的展示上限（出口与投递块共用）。 */
import type { DeliveryTarget } from "./index.ts";

/** 一个出口的展示上限（码点）。 */
export interface DisplayCaps {
  titleMax: number;
  bodyMax: number;
}

/** 各出口的展示上限（值取自 0.2.3 的 channel capabilities）。 */
export const displayCaps: Readonly<Record<DeliveryTarget["type"], DisplayCaps>> = {
  bark: { titleMax: 64, bodyMax: 4096 },
  webhook: { titleMax: 64, bodyMax: 4096 },
  browser: { titleMax: 64, bodyMax: 2048 },
  system: { titleMax: 64, bodyMax: 256 },
};

/** 失败原因上限：状态页只有一行，原因是摘要不是全文（0.2.3 同值）。 */
export const FAILURE_REASON_MAX = 300;

/** 失败原因里附带的响应体摘要上限：各出口自己拼文案，摘要长度是同一条口径。 */
export const RESPONSE_DETAIL_MAX = 200;

/** 按码点截断：定稿与四个出口共用同一份（实现在共享层，这里只是转发，不是第二份副本）。 */
export { truncateCodePoints } from "../../../shared/interface.ts";

/**
 * dsh-notifier channels 域 —— 投递编排（聚合，只做聚合）。
 *
 * 本域实现层的唯一聚合点：声明「投递目标」这个联合，把每个目标分派给各自的出口实现。
 * 它不定义出口的形状，也不做业务——「该发给谁」是裁决层的问题。
 */
import { reason, reasonFromCause } from "../../../shared/interface.ts";
import { sendBark } from "../bark/index.ts";
import type { BarkTarget } from "../bark/type.ts";
import { sendBrowser } from "../browser/index.ts";
import type { BrowserTarget } from "../browser/type.ts";
import { sendSystem } from "../system/index.ts";
import type { SystemTarget } from "../system/type.ts";
import { sendWebhook } from "../webhook/index.ts";
import type { WebhookTarget } from "../webhook/type.ts";
import type { DeliverResult, NotifyMessage } from "./type.ts";

/** 投递目标：出口类型 + 该出口的投递参数（联合在聚合点声明，各出口只交出自己的那一路）。 */
export type DeliveryTarget = BarkTarget | WebhookTarget | BrowserTarget | SystemTarget;

/** 投递能力实现：并行投递，逐目标分派，结果与 `targets` 下标同序。 */
export async function deliverImpl(
  message: NotifyMessage,
  targets: DeliveryTarget[],
): Promise<DeliverResult[]> {
  return Promise.all(targets.map((target) => deliverOne(target, message)));
}

/**
 * 投一个目标，并把「出口违约」收成本域的结果。
 *
 * 出口承诺失败是返回值而不是异常，所以走进 catch 就是违约。在这里收口而不是让它冒给
 * `Promise.all`：一次拒绝会让整批一起失败，调用方只能记一条「全都没发出去」。
 * `stage` 取 `accepted`——违约的出口没给出任何证据；`retryable` 为假——出口本应把失败
 * 做成返回值，抛出来说明它有洞，再投一次只是把同一个洞踩第二遍。
 */
async function deliverOne(target: DeliveryTarget, message: NotifyMessage): Promise<DeliverResult> {
  try {
    // 出口类型是跨边界数据：编译期的联合穷举不代表运行时的值也在枚举里，故留一份原始值给守卫。
    const kind: string = target.type;
    switch (target.type) {
      case "bark":
        return await sendBark(target, message);
      case "webhook":
        return await sendWebhook(target, message);
      case "browser":
        return sendBrowser(target, message);
      case "system":
        return await sendSystem(target, message);
    }
    // 枚举之外的出口没有实现可派发；落成空元素会让下游读 `result.status` 当场 TypeError，
    // 整批结果连同一起来到这一步的出口一起丢，所以这里按「本目标失败」收口。
    return unknownTarget(kind);
  } catch (cause) {
    return {
      status: "failed",
      stage: "accepted",
      reason: reasonFromCause("reasonChannelThrew", cause),
      retryable: false,
    };
  }
}

/**
 * 未知出口类型的失败明细：形状与出口违约那条完全一致，好让调用方只认一套结果。
 * `stage` 取 `accepted`、`retryable` 为假——这个目标根本没被派发出去，没有任何证据可依据。
 */
function unknownTarget(kind: string): DeliverResult {
  return {
    status: "failed",
    stage: "accepted",
    reason: reason("reasonUnknownTarget", { params: { kind } }),
    retryable: false,
  };
}

/**
 * dsh-notifier channels 域 —— 草稿测试（dry-run）的单目标出站（提案 B6）。
 *
 * bypass 清单（与正常管线逐项对照）：
 * - 跳过 enabled 门：直构目标，不读 channel.enabled——新频道默认 false，否则恒 suppressed，
 *   测新频道就永远测不了；
 * - 不走 judge / kindRoutes：只测这一个目标，裁决与路由没有输入；
 * - bypass 节奏（rhythm / withGate）与重试：单次尝试——bark 重试最坏约 33s（2 次退避），
 *   远超服务端 15s 总预算，写死单次，retryable 只如实带回，不执行；
 * - 禁 settle / archive / emitFrame 所涉的一切写面：不调 stores、不 emit 帧；browser 的
 *   emitFrame 接空函数——返回 ok 但不 emit 真通知（面板写明以面板结果为准）；
 * - 能力探测复用共享缓存只读：sendSystem 内部经 platformCapabilities.get 读缓存，
 *   这里不 reset、不替换；读面只传空 logger（B3 禁写面含全部 logger warn）；
 * - system spawn 没有 abort 线：15s 总预算到点后在飞的投递由出口自己的 KILL 8s 回收，
 *   结果丢弃（见 api 域的预算注释与 README 安全模型）。
 *
 * bark / webhook 走 SSRF 安全 fetch（见 secure-fetch.ts），单跳超时复用各出口自己的
 * clamp 再压 15s 上限（dryRunFetchTimeoutMs，表驱动钉住）；system / browser 不走网络，
 * 直接调出口原函数。结果理由在这里统一收口：FAILURE_REASON_MAX 截 detail
 * （RESPONSE_DETAIL_MAX 已在出口内截响应体，STATUS_ERROR_LIMIT 与前者同值 300，
 * 一次截断即同时满足三上限），normalizeReason 收编形态。
 */
import { clampReasonDetail, normalizeReason } from "../../../shared/interface.ts";
import type { ProducedReason } from "../../../shared/interface.ts";
import { sendBark, timeoutMsOf } from "../bark/index.ts";
import { sendBrowser } from "../browser/index.ts";
import { sendSystem } from "../system/index.ts";
import { clampTimeoutSec, sendWebhook } from "../webhook/index.ts";
import { FAILURE_REASON_MAX } from "../deliver/caps.ts";
import type { DeliveryTarget } from "../deliver/index.ts";
import type { DeliverResult, HttpFetch, NotifyMessage } from "../deliver/type.ts";
import { secureFetch } from "./secure-fetch.ts";
import type { SecureFetchPorts } from "./secure-fetch.ts";

/** dry-run 单跳出站超时上限（毫秒）：提案 B4「fetch 强制≤15s」。 */
export const DRY_RUN_FETCH_CAP_MS = 15_000;

/**
 * 单跳超时：复用各出口自己的 clamp（与已保存路径同源），再压 15s 上限。
 * 导出是为了让这条口径可表驱动：超时只落在请求的 deadline 上，从外面读不出来——
 * 「上限被改宽」在行为用例里是绿的（与 clampTimeoutSec 的导出理由同族）。
 */
export function dryRunFetchTimeoutMs(
  target: Extract<DeliveryTarget, { type: "bark" } | { type: "webhook" }>,
): number {
  const base =
    target.type === "bark" ? timeoutMsOf(target) : clampTimeoutSec(target.timeoutSec) * 1000;
  return Math.min(base, DRY_RUN_FETCH_CAP_MS);
}

/**
 * 单目标出站：按目标类型分派，bark / webhook 经安全 fetch，browser / system 直调原函数。
 *
 * @param ports 安全 fetch 的注入面（缺省即真实 DNS + 真实建连；单测注入桩，全程离线）。
 */
export async function dryRunTarget(
  target: DeliveryTarget,
  message: NotifyMessage,
  ports?: SecureFetchPorts,
): Promise<DeliverResult> {
  switch (target.type) {
    case "bark":
      return settled(await sendBark(target, message, dryRunFetch(target, ports)));
    case "webhook":
      return settled(await sendWebhook(target, message, dryRunFetch(target, ports)));
    case "browser":
      // emitFrame 接空函数：返回 ok 但不 emit 真通知（面板写明以面板结果为准，见 B6）。
      return settled(sendBrowser({ ...target, emitFrame: () => {} }, message));
    case "system":
      return settled(await sendSystem(target, message));
  }
}

/** 安全 fetch → 出口要的 HttpFetch 形状：失败抛错（出口收成 request-failed），成功按状态映射。 */
function dryRunFetch(
  target: Extract<DeliveryTarget, { type: "bark" } | { type: "webhook" }>,
  ports?: SecureFetchPorts,
): HttpFetch {
  return (url, init) =>
    secureFetch(
      url,
      {
        method: init.method,
        headers: init.headers,
        body: init.body,
        timeoutMs: dryRunFetchTimeoutMs(target),
      },
      ports ?? {},
    ).then((outcome) => {
      if (!outcome.ok) throw new Error(outcome.cause);
      return {
        ok: outcome.status >= 200 && outcome.status < 300,
        status: outcome.status,
        text: () => Promise.resolve(outcome.body),
        json: () => {
          try {
            return Promise.resolve(JSON.parse(outcome.body) as unknown);
          } catch {
            return Promise.reject(new SyntaxError("响应体不是合法 JSON"));
          }
        },
      };
    });
}

/** 结果理由收口：ok 无理由；失败与空动作的理由截断 + 收编（见模块头三上限说明）。 */
function settled(result: DeliverResult): DeliverResult {
  if (result.status === "ok") return result;
  const normalized = normalizeReason(clampReasonDetail(result.reason, FAILURE_REASON_MAX));
  if (normalized === undefined) return result;
  return { ...result, reason: normalized as ProducedReason };
}

/**
 * dsh-notifier channels 域 —— dry-run 专用 SSRF 安全 fetch（提案 B4，仅此路径）。
 *
 * 已保存路径（sendBark / sendWebhook 的默认实现）保持全局 fetch 语义，一个字不改；
 * 草稿里的 URL 未经用户保存、可指向任意内网地址，故 dry-run 的出站必须过这一道硬闸：
 * - 只认 http/https，拒绝 userinfo（凭据拼进 URL 会留在对端访问日志里）；
 * - 字面量 IP 先按 inet_aton 语义展开（十进制/十六进制/八进制/缩写，一个都不能漏——
 *   漏一种就等于给那种写法开一条直达内网的旁路），再分类；
 * - 主机名经 DNS 全部解析（all:true），逐条分类，一条不公开即整单拒绝（fail-closed）；
 * - 重定向手动跟（redirect:manual），逐跳重解析复检，上限 5 跳；
 * - 建连时把核验过的 IP 钉进 lookup（不再二次解析，关 TOCTOU），连上后验 remoteAddress，
 *   对不上即熔断；TLS 的 SNI 与证书校验仍走原始主机名（只钉地址，不替身份）；
 * - 响应体至多读 16K（与 POST /test 的 BODY_LIMIT 同界，B4「模板头体积以 BODY_LIMIT 为界」
 *   的另一半：回显反射残留也只读这么多，出口再截 200 字符）；
 * - 超时由调用方按「复用出口 clamp 再压 15s 上限」传入，逐跳生效。
 *
 * 纯判定（parseIpLiteral / ipBlockCause）与 IO（DNS / 建连）分开：前者是无 IO 的纯函数，
 * 单测矩阵逐条覆盖反例；后者经 SecureFetchPorts 注入，单测用桩断言「坏地址建连前被拦下」。）
 */
import { promises as dnsPromises } from "node:dns";
import http from "node:http";
import https from "node:https";
import { isIP } from "node:net";

/** DNS 单条应答（getaddrinfo 的原始形态）。 */
export interface DnsAnswer {
  readonly address: string;
  readonly family: number;
}

/** DNS 解析口：默认走系统 getaddrinfo，单测注入桩。 */
export interface SecureDns {
  resolveAll(hostname: string): Promise<DnsAnswer[]>;
}

/** 单跳建连入参（超时已由调用方 clamp，逐跳生效）。 */
export interface PinnedInit {
  readonly method: string;
  readonly headers: Record<string, string>;
  readonly body: string;
  readonly timeoutMs: number;
}

/** 单跳结论：响应（状态 + 至多 16K 的正文）或重定向（只带 Location，不跟）。 */
export type PinnedOutcome =
  | { readonly kind: "response"; readonly status: number; readonly body: string }
  | { readonly kind: "redirect"; readonly location: string };

/** 建连口：默认是钉死 IP 的真实建连，单测注入桩。 */
export interface PinnedTransport {
  (url: URL, ip: string, family: 4 | 6, init: PinnedInit): Promise<PinnedOutcome>;
}

/** 安全 fetch 的注入面（两口都缺省即真实 DNS + 真实建连）。 */
export interface SecureFetchPorts {
  readonly dns?: SecureDns;
  readonly transport?: PinnedTransport;
}

/** 安全 fetch 的出站入参。 */
export interface SecureFetchInit {
  readonly method: string;
  readonly headers: Record<string, string>;
  readonly body: string;
  /** 单跳超时（毫秒）：调用方已按「出口 clamp ∩ 15s 上限」算好，这里只执行。 */
  readonly timeoutMs: number;
}

/** 安全 fetch 结论：成功带状态与正文，失败只带一句话（调用方按出口 code 包装进 reason.detail）。 */
export type SecureFetchOutcome =
  | { readonly ok: true; readonly status: number; readonly body: string }
  | { readonly ok: false; readonly cause: string };

/** 解析后的 IP 字面量（v4 按 inet_aton 展开成 4 个字节，v6 展开成 8 个 16 位字）。 */
export type ParsedIp =
  | {
      readonly family: 4;
      readonly octets: readonly [number, number, number, number];
      readonly text: string;
    }
  | { readonly family: 6; readonly words: readonly number[]; readonly text: string };

/** 重定向上限：逐跳都要重过整道闸，太多跳说明对端在带我们逛。 */
const MAX_REDIRECTS = 5;

/** 响应体读取上限（字节）：与 POST /test 的 BODY_LIMIT 同界，见模块头。 */
const RESPONSE_CAP = 16 * 1024;

/** 跟随的重定向状态码：只跟带 Location 的这五个，其余 3xx 按普通响应当（出口判非 2xx 失败）。 */
const REDIRECT_STATUS = new Set([301, 302, 303, 307, 308]);

/**
 * 安全 fetch：整单只做一次「解析—核验—建连—读数」的循环，重定向每跳重来一遍。
 * 302/303 也按 POST 原样重发（307/308 语义）：测试投递的 body 不能在跳转里丢，丢了等于
 * 「测的是 A、打的是 B 的空包」。上限 5 跳，超了即失败（不是静默停在最后一跳）。
 */
export async function secureFetch(
  input: string,
  init: SecureFetchInit,
  ports: SecureFetchPorts = {},
): Promise<SecureFetchOutcome> {
  const dns = ports.dns ?? defaultDns;
  const transport = ports.transport ?? realTransport;
  let current = input;
  for (let hop = 0; hop <= MAX_REDIRECTS; hop += 1) {
    let url: URL;
    try {
      url = new URL(current);
    } catch {
      return failed("URL 解析失败");
    }
    if (url.protocol !== "http:" && url.protocol !== "https:") {
      return failed("仅允许 http(s)，拒绝 " + url.protocol);
    }
    if (url.username !== "" || url.password !== "") {
      return failed("URL 不得内嵌 userinfo（凭据只能走请求头）");
    }
    const pinned = await pinHost(url.hostname, dns);
    if (!pinned.ok) return failed(pinned.cause);
    let outcome: PinnedOutcome;
    try {
      outcome = await transport(url, pinned.ip, pinned.family, {
        method: init.method,
        headers: init.headers,
        body: init.body,
        timeoutMs: init.timeoutMs,
      });
    } catch (cause) {
      return failed(cause instanceof Error ? cause.message : String(cause));
    }
    if (outcome.kind !== "redirect") {
      return { ok: true, status: outcome.status, body: outcome.body };
    }
    if (hop === MAX_REDIRECTS) return failed("重定向过多（超过 " + MAX_REDIRECTS + " 跳）");
    try {
      current = new URL(outcome.location, url).toString();
    } catch {
      return failed("重定向地址非法");
    }
  }
  return failed("重定向过多（超过 " + MAX_REDIRECTS + " 跳）");
}

function failed(cause: string): SecureFetchOutcome {
  return { ok: false, cause };
}

/** 默认 DNS：系统 getaddrinfo 全量解析（只取地址，不做任何过滤——过滤是分类器的事）。 */
const defaultDns: SecureDns = {
  resolveAll: (hostname) => dnsPromises.lookup(hostname, { all: true }),
};

/**
 * 主机名 → 可建连的 IP（已核验）：字面量直接分类，主机名全量解析后逐条分类。
 * 任一条不公开即整单拒绝——「有一条能连」不等于「连的 assault 那条公开」，解析与建连之间
 * 没有复检窗口：返回的 ip 即建连钉死的地址（见 realTransport 的 lookup）。
 */
async function pinHost(
  hostname: string,
  dns: SecureDns,
): Promise<{ ok: true; ip: string; family: 4 | 6 } | { ok: false; cause: string }> {
  const literal = parseIpLiteral(hostname);
  if (literal !== undefined) {
    const cause = ipBlockCause(literal);
    return cause === undefined
      ? { ok: true, ip: literal.text, family: literal.family }
      : { ok: false, cause };
  }
  let answers: DnsAnswer[];
  try {
    answers = await dns.resolveAll(hostname);
  } catch {
    return { ok: false, cause: "DNS 解析失败：" + hostname };
  }
  if (answers.length === 0) return { ok: false, cause: "DNS 无解析结果：" + hostname };
  for (const answer of answers) {
    const parsed = parseIpLiteral(answer.address);
    const cause =
      parsed === undefined ? "DNS 返回非法地址：" + answer.address : ipBlockCause(parsed);
    if (cause !== undefined) {
      return { ok: false, cause: "DNS 命中非公开地址（" + cause + "），整单拒绝" };
    }
  }
  const first = answers[0];
  return { ok: true, ip: first.address, family: first.family === 6 ? 6 : 4 };
}

/**
 * IP 字面量解析：先按 inet_aton 语义试 v4（十进制/八进制/十六进制/1~4 段缩写全认——
 * getaddrinfo 全认，少认一种就等于给那种写法开旁路），再试标准 v6。都不是即不是字面量
 * （调用方走 DNS）。FQDN 尾点先剥掉：解析器认它，分类器不能因为多个点就认不出回环。
 */
export function parseIpLiteral(text: string): ParsedIp | undefined {
  const stripped = text.trim().replace(/\.$/, "");
  const v4 = parseIpv4Loose(stripped);
  if (v4 !== undefined) return { family: 4, octets: v4, text: v4.join(".") };
  const noBracket =
    stripped.startsWith("[") && stripped.endsWith("]") ? stripped.slice(1, -1) : stripped;
  if (isIP(noBracket) !== 6) return undefined;
  const words = expandIpv6(noBracket.toLowerCase());
  if (words === undefined) return undefined;
  return { family: 6, words, text: noBracket.toLowerCase() };
}

/**
 * inet_aton 语义的 v4 解析：每段按前缀定基数（0x 十六、首 0 八进制、其余十进制），
 * 段数决定拼法（1 段 32 位、2 段 8+24、3 段 8+8+16、4 段逐字节），越界即非法。
 * 与系统解析器同语义是安全要求，不是兼容癖好：两边对「2130706433 是不是 127.0.0.1」
 * 给出不同答案的那一刻，分类器就被绕过了。
 */
function parseIpv4Loose(text: string): [number, number, number, number] | undefined {
  if (text === "" || text.includes(":")) return undefined;
  const parts = text.split(".");
  if (parts.length < 1 || parts.length > 4) return undefined;
  const values: number[] = [];
  for (const part of parts) {
    if (part === "") return undefined;
    let base = 10;
    let digits = part;
    if (part.startsWith("0x") || part.startsWith("0X")) {
      base = 16;
      digits = part.slice(2);
    } else if (part.length > 1 && part.startsWith("0")) {
      base = 8;
      digits = part.slice(1);
    }
    if (digits === "" || !/^[0-9a-fA-F]+$/.test(digits)) return undefined;
    if (base === 10 && /[^0-9]/.test(digits)) return undefined;
    if (base === 8 && /[^0-7]/.test(digits)) return undefined;
    const value = Number.parseInt(digits, base);
    if (!Number.isSafeInteger(value)) return undefined;
    values.push(value);
  }
  const full =
    values.length === 1
      ? values[0]
      : values.length === 2
        ? values[0] * 2 ** 24 + values[1]
        : values.length === 3
          ? values[0] * 2 ** 24 + values[1] * 2 ** 16 + values[2]
          : values[0] * 2 ** 24 + values[1] * 2 ** 16 + values[2] * 2 ** 8 + values[3];
  const limits = [0xffffffff, 0xffffff, 0xffff, 0xff];
  for (let index = 0; index < values.length; index += 1) {
    if (values[index] < 0 || values[index] > (limits[index] ?? 0xff)) return undefined;
  }
  if (full < 0 || full > 0xffffffff) return undefined;
  return [
    Math.floor(full / 2 ** 24) % 256,
    Math.floor(full / 2 ** 16) % 256,
    Math.floor(full / 2 ** 8) % 256,
    full % 256,
  ];
}

/**
 * IP 分类：返回阻断原因，是 undefined 即公开可连。v4 按字节判，v6 按 16 位字判
 * （三类内嵌 v4——映射/兼容/6to4——拆包后按内层判：外层全球可达不代表内层也是）。
 *
 * 未逐项注释「为什么是这个前缀」：前缀与掩码即判据本身，注释复述一遍只是第二份事实源；
 * 每个分支的文案带前缀写法，改前缀时文案与判据在同一行一起改。
 */
export function ipBlockCause(parsed: ParsedIp): string | undefined {
  if (parsed.family === 4) return v4BlockCause(parsed.octets);
  return v6BlockCause(parsed.words);
}

function v4BlockCause(octets: readonly [number, number, number, number]): string | undefined {
  const first = octets[0] ?? 0;
  const second = octets[1] ?? 0;
  const third = octets[2] ?? 0;
  if (first === 0) return "未指定地址（0.0.0.0/8）";
  if (first === 10) return "私网地址（10.0.0.0/8）";
  if (first === 172 && second >= 16 && second <= 31) return "私网地址（172.16.0.0/12）";
  if (first === 192 && second === 168) return "私网地址（192.168.0.0/16）";
  if (first === 100 && second >= 64 && second <= 127) return "运营商级 NAT 保留段（100.64.0.0/10）";
  if (first === 127) return "回环地址（127.0.0.0/8）";
  if (first === 169 && second === 254) return "链路本地地址（169.254.0.0/16，含云元数据地址）";
  if (first === 192 && second === 0 && (third === 0 || third === 2)) {
    return "IETF 保留段（192.0.0.0/24，含文档网段）";
  }
  if (first === 192 && second === 88 && third === 99)
    return "已退役的 6to4 中继段（192.88.99.0/24）";
  if (
    (first === 192 && second === 0 && third === 113) ||
    (first === 198 && second === 51 && third === 100) ||
    (first === 203 && second === 0 && third === 113)
  ) {
    return "文档保留段（TEST-NET，不可路由）";
  }
  if (first === 198 && (second === 18 || second === 19)) return "基准测试保留段（198.18.0.0/15）";
  if (first >= 224 && first <= 239) return "组播地址（224.0.0.0/4）";
  if (first >= 240) return "保留地址（240.0.0.0/4，含广播地址）";
  return undefined;
}

function v6BlockCause(words: readonly number[]): string | undefined {
  if (words.length !== 8) return "IPv6 解析失败";
  if (words.every((word) => word === 0)) return "未指定地址（::）";
  const headZero7 = words.slice(0, 7).every((word) => word === 0);
  if (headZero7 && words[7] === 1) return "回环地址（::1）";
  const headZero5 = words.slice(0, 5).every((word) => word === 0);
  if (headZero5 && words[5] === 0xffff) return v4BlockCause(innerV4(words));
  if (headZero5 && words[5] === 0) return v4BlockCause(innerV4(words));
  // 6to4 的 v4 藏在第 2~3 个字（2002:V4HIGH:V4LOW::/48），与映射/兼容的末 32 位不同布局。
  if (words[0] === 0x2002) return v4BlockCause(sixToFourInner(words));
  if (((words[0] ?? 0) & 0xffc0) === 0xfe80) return "链路本地地址（fe80::/10）";
  if (((words[0] ?? 0) & 0xfe00) === 0xfc00) return "唯一本地地址（fc00::/7）";
  if (((words[0] ?? 0) & 0xff00) === 0xff00) return "组播地址（ff00::/8）";
  if (words[0] === 0x2001 && words[1] === 0x0db8) return "文档保留段（2001:db8::/32）";
  if (words[0] === 0x2001 && words[1] === 0) return "Teredo 保留段（2001::/32）";
  return undefined;
}

/** 内嵌 v4 的末 32 位：映射/兼容两支共用，调用前已确认布局。 */
function sixToFourInner(words: readonly number[]): [number, number, number, number] {
  const high = words[1] ?? 0;
  const low = words[2] ?? 0;
  return [(high >>> 8) & 0xff, high & 0xff, (low >>> 8) & 0xff, low & 0xff];
}

/** 内嵌 v4 的末 32 位：映射/兼容两支共用，调用前已确认布局。 */
function innerV4(words: readonly number[]): [number, number, number, number] {
  const high = words[6] ?? 0;
  const low = words[7] ?? 0;
  return [(high >>> 8) & 0xff, high & 0xff, (low >>> 8) & 0xff, low & 0xff];
}

/**
 * v6 文本展开成 8 个字：点分十进制尾（::ffff:1.2.3.4）先按 v4 收成两个字，
 * 剩下的头按 :: 切开补零。非法即 undefined（调用方按「不是字面量」走 DNS）。
 */
function expandIpv6(text: string): number[] | undefined {
  let head = text;
  const tailWords: number[] = [];
  if (text.includes(".")) {
    const at = text.lastIndexOf(":");
    if (at === -1) return undefined;
    const v4 = parseIpv4Loose(text.slice(at + 1));
    if (v4 === undefined) return undefined;
    tailWords.push(v4[0] * 256 + v4[1], v4[2] * 256 + v4[3]);
    head = text.slice(0, at);
    if (head.endsWith(":")) head = head.slice(0, -1);
    // 兼容形的头被剥到只剩空串（::10.0.0.1 → ""）：它就是全压缩的 ::，不能按无压缩解析。
    if (head === "") head = "::";
  }
  const halves = head.split("::");
  if (halves.length > 2) return undefined;
  if (halves.length === 1) {
    const all = parseHextets(halves[0] ?? "");
    if (all === undefined || all.length !== 8 - tailWords.length) return undefined;
    return [...all, ...tailWords];
  }
  const left = parseHextets(halves[0] ?? "");
  const right = parseHextets(halves[1] ?? "");
  if (left === undefined || right === undefined) return undefined;
  const missing = 8 - tailWords.length - left.length - right.length;
  if (missing < 1) return undefined;
  return [...left, ...new Array<number>(missing).fill(0), ...right, ...tailWords];
}

function parseHextets(group: string): number[] | undefined {
  if (group === "") return [];
  const out: number[] = [];
  for (const part of group.split(":")) {
    if (!/^[0-9a-fA-F]{1,4}$/.test(part)) return undefined;
    out.push(Number.parseInt(part, 16));
  }
  return out;
}

/**
 * 钉死建连：lookup 回调直接交出核验过的 IP（不再二次解析，关 TOCTOU），连上后验
 * remoteAddress（防 lookup 与建连之间地址被换），TLS 的 SNI 与证书校验仍走原始主机名
 * （只钉地址，不替身份——钉身份等于自签信任）。响应体按 RESPONSE_CAP 截流，3xx 只读
 * Location 不跟（跟不跟由外层循环逐跳复检后决定）。
 */
/**
 * 真实钉死建连（realTransport 的本体）：导出给单测直测传输层——对回环起真实建连，
 * 全程离线（不断言公网）。生产路径经 SecureFetchPorts.transport 默认值走同一条。
 */
export function realTransport(
  url: URL,
  ip: string,
  family: 4 | 6,
  init: PinnedInit,
): Promise<PinnedOutcome> {
  return new Promise<PinnedOutcome>((resolve, reject) => {
    let settled = false;
    const settleResolve = (outcome: PinnedOutcome): void => {
      if (settled) return;
      settled = true;
      resolve(outcome);
    };
    const settleReject = (cause: unknown): void => {
      if (settled) return;
      settled = true;
      reject(cause instanceof Error ? cause : new Error(String(cause)));
    };
    const lib = url.protocol === "https:" ? https : http;
    const req = lib.request(
      url,
      {
        method: init.method,
        headers: init.headers,
        lookup: (_host, _options, callback) => callback(null, ip, family),
      },
      (res) => {
        const location = res.headers.location;
        if (
          typeof res.statusCode === "number" &&
          REDIRECT_STATUS.has(res.statusCode) &&
          typeof location === "string"
        ) {
          res.resume();
          settleResolve({ kind: "redirect", location });
          return;
        }
        const chunks: Buffer[] = [];
        let size = 0;
        res.on("data", (chunk: Buffer) => {
          if (size >= RESPONSE_CAP) return;
          // 超界的块只留前 room 个字节：整块丢弃会让一次大响应读成空串（32K 单块实测）。
          const room = RESPONSE_CAP - size;
          chunks.push(chunk.length > room ? chunk.subarray(0, room) : chunk);
          size += chunk.length;
          if (size >= RESPONSE_CAP) {
            // 到界即按已有前缀结算并掐流：不再等 end（destroy 后它不会来）。
            settleResolve({
              kind: "response",
              status: res.statusCode ?? 0,
              body: Buffer.concat(chunks).toString("utf8"),
            });
            req.destroy();
          }
        });
        res.on("end", () =>
          settleResolve({
            kind: "response",
            status: res.statusCode ?? 0,
            body: Buffer.concat(chunks).toString("utf8"),
          }),
        );
        res.on("error", settleReject);
      },
    );
    // socket 事件只代表「套接字已分配」，remoteAddress 在连上之前是空串——空串即熔断会把
    // 每一次建连都误杀。空时挂一次 connect 再验（单线程内无竞态：事件不可能插在本次
    // handler 中间触发）；https 另挂 secureConnect，哪个先到都只做同一件事（verify 幂等）。
    req.on("socket", (socket) => {
      const verify = (): void => {
        const remote = socket.remoteAddress ?? "";
        if (remote === "") return;
        if (!sameEndpoint(remote, ip)) {
          settleReject(
            new Error("对端地址与核验地址不一致，已熔断（remoteAddress=" + remote + "）"),
          );
          req.destroy();
        }
      };
      if ((socket.remoteAddress ?? "") === "") {
        socket.once("connect", verify);
        socket.once("secureConnect", verify);
      } else {
        verify();
      }
    });
    req.on("timeout", () => {
      settleReject(new Error("请求超时（" + init.timeoutMs + "ms）"));
      req.destroy();
    });
    req.on("error", settleReject);
    req.setTimeout(init.timeoutMs);
    req.end(init.body);
  });
}

/** 建连端点比对：大小写/括号归一，v4 映射（::ffff:1.2.3.4）视同其内层 v4。 */
function sameEndpoint(remote: string, expected: string): boolean {
  const left = remote
    .trim()
    .toLowerCase()
    .replace(/^\[|\]$/g, "");
  const right = expected
    .trim()
    .toLowerCase()
    .replace(/^\[|\]$/g, "");
  if (left === right) return true;
  const mapped = /^::ffff:(\d+\.\d+\.\d+\.\d+)$/.exec(left);
  return mapped !== null && mapped[1] === right;
}

/**
 * dsh-notifier channels 域 —— 系统出口：探测平台能力、构造命令、执行命令。
 * 命令一律 `[bin, ...args]` 参数数组（零 shell 拼接）。1 秒节流不在这里（归管线）。
 *
 * 终态判据分两条，不再用「零动作」当统一口径：**执行过动作而它失败了**就是失败（有失败证据）；
 * **一条命令都构造不出来**是空动作（没有可失败环节），成因经 `reason` 的 code 带出去。
 *
 * 自播从「取首个可用播放器」改成**按回退链逐条试、首个成功即停**，且失败要自证：判据是退出码加
 * 实测致命标记（**不是**「stderr 必须为空」，理由见 `players.ts`）。Linux 上主题文件缺失时用
 * 运行时合成的 WAV（`tone-file.ts`）——这正是 #783 的现场：宿主有播放设备却没装 freedesktop
 * 音色包。
 */
import { FOLLOW_SYSTEM_TONE, TONES } from "../../../../shared/interface.ts";
import type { LoggerPort, ReasonCode, ReasonParams } from "../../../shared/interface.ts";
import { reason } from "../../../shared/interface.ts";
import { displayCaps, truncateCodePoints } from "../deliver/caps.ts";
import type { DeliverResult, NotifyMessage, ToneSetting } from "../deliver/type.ts";
import { platformCapabilities, systemDeps } from "./deps.ts";
import type { ChildHandle } from "./deps.ts";
import {
  LINUX_PLAYERS,
  playerSpec,
  playFailure,
  playFailureSummary,
  warnWorthy,
} from "./players.ts";
import type { PlayerSpec, PlayFailure } from "./players.ts";
import { resolveToneSource, stageToneSource, unstageToneAudio } from "./tone-file.ts";
import type {
  CommandFacts,
  CommandOutcome,
  PlatformProbe,
  SystemCommandOptions,
  SystemTarget,
} from "./type.ts";

/** 探测超时（毫秒）：探测不许拖住第一次投递。 */
const PROBE_TIMEOUT_MS = 3000;
/** 子进程兜底杀进程时限：通知与音频进程都是短命任务。 */
const KILL_TIMEOUT_MS = 8000;
/** stderr 收集上限与进日志的尾部长度（字符）。 */
const STDERR_TAIL_MAX = 512;
const STDERR_LOG_MAX = 300;

/** 探测本平台能力（异步一次；不用 spawnSync 阻塞事件循环）。 */
export async function probePlatform(toastScript: string): Promise<PlatformProbe> {
  const deps = systemDeps();
  const platform = deps.platform;
  // macOS 走 osascript、Windows 走 PowerShell，都不依赖 notify-send，故不探测
  const notifySendAvailable =
    platform === "darwin" || platform === "win32"
      ? false
      : await probeCommand("notify-send", ["--version"]);
  const players =
    platform === "linux" ? await probePlayers() : platform === "darwin" ? ["afplay"] : [];
  return {
    platform,
    toastScriptAvailable: deps.existsSync(toastScript),
    notifySendAvailable,
    players,
  };
}

/**
 * 候选播放器**并行**探测，返回**全部**命中者（顺序 = 表序 = 回退链尝试序）。
 *
 * 并行是刻意的语义变更：命中即停那版最坏情况要串行等 4 次超时，而探测会挡住第一次投递；
 * 换来的是「最坏探测时延仍是一次超时」。代价是每次探测起 4 个子进程。
 */
async function probePlayers(): Promise<readonly string[]> {
  const probed = await Promise.all(
    LINUX_PLAYERS.map(async (player) => ((await probePlayer(player)) ? player.bin : undefined)),
  );
  return probed.filter((bin): bin is string => bin !== undefined);
}

/**
 * 该播放器是否**不依赖声音服务**（能力面据此把 linux 判成 `ok` / `degraded`）。
 *
 * 数据只有一处：`LINUX_PLAYERS` 那一行的 `needsServer`。表里没有的 bin 一律回 `false`——
 * 「不在表里」不等于「不需要声音服务」，而 `ok` 的语义恰恰是「命中的播放器里至少有一个**已知**
 * 能直连出声」；把不认识的算作 serverless，就是本增量要消灭的那种「把测不准的事写成 ok」。
 * linux 上这一分支结构上不可达（`probePlayers` 探的就是这张表），故它只是一条不制造假 ok 的兜底。
 */
export function isServerlessPlayer(bin: string): boolean {
  return playerSpec(bin)?.needsServer === false;
}

/** 一个候选的探测：表内参数按序试，任一跑得起来即命中（ffplay 的 `--version` 实测 exit 1）。 */
async function probePlayer(player: PlayerSpec): Promise<boolean> {
  for (const args of player.probeArgs) {
    if (await probeCommand(player.bin, args)) return true;
  }
  return false;
}

/** 探测一条命令是否可用：版本参数既不弹通知也不发声。 */
function probeCommand(bin: string, args: readonly string[]): Promise<boolean> {
  return new Promise((resolve) => {
    systemDeps().execFile(bin, args, { timeout: PROBE_TIMEOUT_MS }, (failed) => {
      resolve(!failed);
    });
  });
}

/**
 * 构造弹窗命令；空数组 = 本平台给不出这条命令。
 * silent = 声音关闭或出口要自播（自播时不静音会响两声）。
 */
export function buildSystemCommand(
  probe: PlatformProbe,
  title: string,
  message: string,
  options: SystemCommandOptions,
): readonly string[] {
  const silent = options.sound === false || options.selfPlay;
  if (probe.platform === "win32") {
    if (!probe.toastScriptAvailable) return [];
    // PS 5.1 的 -File 对 `-Name=Value` 不做命名参数绑定，裸 dash token 又会被当成下一个
    // 参数名；base64 字母表无空格无引号，彻底脱离命令行 tokenizer 的歧义面
    const payload = Buffer.from(JSON.stringify({ title, message, silent }), "utf8").toString(
      "base64",
    );
    return [
      "powershell",
      "-NoProfile",
      "-NonInteractive",
      "-ExecutionPolicy",
      "Bypass",
      "-File",
      options.toastScript,
      "-Payload",
      payload,
    ];
  }
  if (probe.platform === "darwin") {
    // osascript 脚本串里转义 \ 与 "、换行换空格（脚本语法不接受裸换行）
    const escape = (text: string) =>
      text.replace(/\\/gu, "\\\\").replace(/"/gu, '\\"').replace(/\n/gu, " ");
    const tone = options.sound;
    // 音色事实只有一份：未知音色与 `sound: true` 都落到「跟随系统默认音」那一档。
    const spec =
      typeof tone === "string" && Object.hasOwn(TONES, tone)
        ? TONES[tone]
        : TONES[FOLLOW_SYSTEM_TONE];
    // 声名缺失时不能给空串：`sound name ""` 在 osascript 里是静默不响，而不是退回默认音。
    const named = spec.darwinSound ?? "Glass";
    const soundName = silent ? "" : ` sound name "${named}"`;
    return [
      "osascript",
      "-e",
      `display notification "${escape(message)}" with title "${escape(title)}"${soundName}`,
    ];
  }
  if (!probe.notifySendAvailable) return [];
  // 恒带 suppress-sound：各 DE 对 sound hint 支持参差，发声一律由出口自播承担
  return ["notify-send", "-h", "boolean:suppress-sound:true", title, message];
}

/** 一条自播命令：argv + 它的判据来源（Linux 播放器表上的那一行；darwin/win32 只看退出码）。 */
export interface ToneCommand {
  readonly command: readonly string[];
  readonly player?: PlayerSpec;
}

/**
 * 构造自播命令链：Linux 上链上每个命中候选各一条命令（argv 随播放器不同），darwin/win32 是平台
 * 播放器的一条。`file` 必须是**已存在**的绝对路径（主题文件或本次落的临时合成文件），
 * 「素材有没有」由 `prepareSound` 判，不在这里重判。
 */
export function buildSoundCommands(probe: PlatformProbe, file: string): readonly ToneCommand[] {
  if (probe.platform === "darwin") return [{ command: ["afplay", file] }];
  if (probe.platform === "win32") {
    // 路径不拼进命令串：固定骨架读 $args[0]，白名单 wav 绝对路径作为独立 argv 传入
    const play = "$p=$args[0]; (New-Object System.Media.SoundPlayer $p).PlaySync()";
    return [
      {
        command: [
          "powershell",
          "-NoProfile",
          "-NonInteractive",
          "-ExecutionPolicy",
          "Bypass",
          "-Command",
          play,
          file,
        ],
      },
    ];
  }
  // 取不到表行说明名单漂了：宁可这一条不试，也不要就地拍一个 argv 出来
  return probe.players
    .map((bin) => playerSpec(bin))
    .filter((player): player is PlayerSpec => player !== undefined)
    .map((player) => ({ command: [player.bin, ...player.fileArgs(file)], player }));
}

/**
 * 自播判定：linux 任何非静音都自播（DE 的 sound hint 不可依赖）；darwin 只在只响不弹
 * 时自播；win32 指定音色或只响不弹时自播。
 */
export function shouldSelfPlay(pop: boolean, tone: boolean | string, platform: string): boolean {
  if (tone === false) return false;
  if (platform === "linux") return true;
  if (platform === "darwin") return !pop;
  if (platform === "win32") return typeof tone === "string" || !pop;
  return false;
}

/**
 * 执行一条命令，把任何退出方式**原样收敛成事实**：不外抛、不做成败判定（判据归调用方）。
 * 必须挂 `error` 监听：原生二进制缺失时无人接住的 error 事件会把宿主进程打挂
 * （历史版本在 macOS 上直接 spawn 缺失的 powershell 崩过）。
 *
 * stderr 一律接管道：音频判据要读它（无头 Linux 上它是唯一的自证面），Windows 的 PS 诊断也只在它上面。
 */
function run(command: readonly string[]): Promise<CommandFacts> {
  const deps = systemDeps();
  return new Promise((resolve) => {
    let child: ChildHandle;
    try {
      child = deps.spawn(command, { collectStderr: true });
    } catch (cause) {
      resolve({
        outcome: {
          kind: "spawn-threw",
          cause: cause instanceof Error ? cause.message : String(cause),
        },
        stderr: "",
      });
      return;
    }
    // 限长收集 stderr 尾部：无上限收集会被一条长诊断撑爆
    let stderrTail = "";
    child.onStderr((chunk) => {
      if (stderrTail.length < STDERR_TAIL_MAX) stderrTail += chunk.toString("utf8");
    });
    let settled = false;
    const settle = (outcome: CommandOutcome): void => {
      if (settled) return;
      settled = true;
      clearTimeout(killer);
      resolve({ outcome, stderr: stderrTail });
    };
    // 结局先到就清掉定时器，别让已回收的进程再挨一刀
    const killer = setTimeout(() => {
      try {
        child.kill();
      } catch {
        // 子进程可能已退出：杀不掉不影响结论
      }
      // 子进程忽略 SIGTERM 时 onExit 永远不到：在这里就地结算，否则 `await` 永久挂着（零日志零落盘）
      settle({ kind: "timeout" });
    }, KILL_TIMEOUT_MS);
    child.onExit((exit) =>
      settle(exit.exited ? { kind: "exit", code: exit.code } : { kind: "killed" }),
    );
    child.onError((cause) => settle({ kind: "spawn-error", cause: cause.message }));
  });
}

/**
 * 非音频命令（弹窗）的失败告警：只有退出码 0 是成功。ffplay 上量到的致命标记表**不是**它的成败语义
 * ——`notify-send` 与 PowerShell 的 stderr 内容与音频播放无关，套过来会把它们的正常输出判成失败。
 */
function popupFailureWarn(bin: string, facts: CommandFacts): string | undefined {
  const outcome = facts.outcome;
  const tail = facts.stderr.trim();
  const detail = tail === "" ? "" : `：${tail.slice(-STDERR_LOG_MAX)}`;
  if (outcome.kind === "exit") {
    return outcome.code === 0
      ? undefined
      : `dsh-notifier: 命令退出码异常（${bin} exit ${outcome.code}）${detail}`;
  }
  if (outcome.kind === "spawn-threw")
    return `dsh-notifier: 命令启动失败（${bin}）: ${outcome.cause}`;
  if (outcome.kind === "spawn-error") return `dsh-notifier: 命令不可用（${bin}）: ${outcome.cause}`;
  if (outcome.kind === "timeout") return `dsh-notifier: 命令超时未退出（${bin}），已按失败结算`;
  // 被信号杀死多数是我们自己的超时兜底：那是主动行为，按异常刷屏会淹掉真正的失败
  return undefined;
}

/** 跑一条非音频命令：日志与成败都在这里收口（原始事实来自 `run()`）。 */
async function runCommand(command: readonly string[], logger: LoggerPort): Promise<boolean> {
  const facts = await run(command);
  const warn = popupFailureWarn(commandNameOf(command), facts);
  if (warn !== undefined) logger.warn(warn);
  return facts.outcome.kind === "exit" && facts.outcome.code === 0;
}

/** 回退链的结论：成功与否 + 全失败时的成因摘要（进 `reason.detail`，可诊断）。 */
interface ChainOutcome {
  readonly ok: boolean;
  readonly detail: string;
}

/**
 * 按回退链逐条试播，**首个成功即停**（继续试就是第二声）。中间候选的失败一律不进日志——只有整条链
 * 都失败、且至少有一个候选的失败值得出声时才留**一条**，否则一次投递会刷出四条 warn。
 *
 * 例外是「被信号杀死」：那多数是我们自己的兜底（主动行为），按异常刷屏会淹掉真失败。
 */
async function runSoundChain(
  commands: readonly ToneCommand[],
  logger: LoggerPort,
): Promise<ChainOutcome> {
  const breakdowns: string[] = [];
  let worthy = false;
  for (const item of commands) {
    const facts = await run(item.command);
    const failure = playFailure(item.player, facts);
    if (failure === undefined) return { ok: true, detail: "" };
    breakdowns.push(summarize(item, failure, facts));
    worthy ||= warnWorthy(failure);
  }
  if (worthy) logger.warn(`dsh-notifier: 提示音播放失败：${breakdowns.join("；")}`);
  return { ok: false, detail: breakdowns.join("；") };
}

/** 一条候选失败的摘要：成因文字来自播放器判据，stderr 尾部在这里按日志上限截一次。 */
function summarize(item: ToneCommand, failure: PlayFailure, facts: CommandFacts): string {
  const tail = facts.stderr.trim();
  return playFailureSummary(
    commandNameOf(item.command),
    failure,
    tail === "" ? "" : tail.slice(-STDERR_LOG_MAX),
  );
}

/** 本次自播的准备结论：命令链就绪（可能带着临时文件）、放不出声、或临时目录写不进去。 */
type SoundPrep =
  | { readonly kind: "ready"; readonly commands: readonly ToneCommand[]; readonly staged?: string }
  | { readonly kind: "empty" }
  | { readonly kind: "unwritable"; readonly cause: string };

const NO_SOUND: SoundPrep = { kind: "empty" };

/**
 * 备好本次自播：主题文件优先，Linux 上候选全缺时才把合成音落到临时文件；再按回退链构造命令。
 * 一个候选播放器都没有时**不落盘**——命令根本构造不出来，落了也得马上删。
 */
function prepareSound(probe: PlatformProbe, tone: string): SoundPrep {
  if (probe.platform === "linux" && probe.players.length === 0) return NO_SOUND;
  const source = resolveToneSource(probe.platform, tone);
  if (source.kind === "none") return NO_SOUND;
  if (source.kind === "theme") {
    const commands = buildSoundCommands(probe, source.path);
    return commands.length === 0 ? NO_SOUND : { kind: "ready", commands };
  }
  const staged = stageToneSource(source.bytes);
  if (!staged.ok) return { kind: "unwritable", cause: staged.cause };
  const commands = buildSoundCommands(probe, staged.path);
  if (commands.length === 0) {
    unstageToneAudio(staged.path);
    return NO_SOUND;
  }
  return { kind: "ready", commands, staged: staged.path };
}

/**
 * 只响不弹分支（原 sendSystem 的 !popup 段）：声音是唯一动作。
 * 临时文件写不进去 = 一条命令都构造不出来——终态 skipped；放不出声同理。
 */
async function runSoundOnly(
  prep: SoundPrep,
  target: SystemTarget,
  probe: PlatformProbe,
): Promise<DeliverResult> {
  // 只响不弹：声音是唯一动作。临时文件写不进去 = 一条命令都构造不出来——本次没有可执行的动作，
  // 终态是 `skipped`（`failed` 的定义是「执行过动作而它失败了」），但成因要能查。
  if (prep.kind === "unwritable") return unwritableSound(target, prep.cause);
  // `!selfPlay` 只可能是枚举外的平台（三平台里 linux 恒自播，darwin / win32 在 `!pop` 时都自播）；
  // 它和「放不出声」是同一件事：本次没有可执行的动作。
  if (prep.kind !== "ready") return unexecutable(target, probe);
  const played = await playChain(prep, target);
  return played.ok
    ? delivered()
    : failed("reasonSystemSoundFailed", { bin: chainBin(prep.commands) }, played.detail);
}

/**
 * 弹窗路径下播放未就绪分支（原 sendSystem 的 prep !== ready 段，需弹窗已构造）。
 * 空动作优先判：一条命令都没构造出来时，「弹窗失败」与「声音失败」都无从谈起。
 * 弹窗已经出去了：声音是尽力而为，但成因仍要留**一条** warn。
 */
function handleUnreadyPrepWithPopup(
  prep: Exclude<SoundPrep, { readonly kind: "ready" }>,
  pop: readonly string[],
  popRan: boolean,
  popOk: boolean,
  target: SystemTarget,
  probe: PlatformProbe,
): DeliverResult {
  // 空动作优先判：一条命令都没构造出来时，「弹窗失败」与「声音失败」都无从谈起。这一格旧实现
  // 在 linux / darwin 上是零输出、零状态、零日志——正是本次要修的静默。
  if (!popRan) {
    return prep.kind === "unwritable"
      ? unwritableSound(target, prep.cause)
      : unexecutable(target, probe);
  }
  // 弹窗已经出去了：声音这一格是尽力而为，但成因仍要留**一条** warn。
  if (prep.kind === "unwritable") target.logger.warn(toneUnwritableWarn(prep.cause));
  return popOk ? delivered() : failed("reasonSystemPopupFailed", { bin: commandNameOf(pop) });
}

/**
 * 弹窗路径下播放就绪后的收尾（原 sendSystem 尾段：打包缺陷 warn + 双失败判定）。
 * 声音只在它是本次唯一动作时才翻转终态；toast 已经出去时声音是尽力而为。
 */
function finishPopupWithSound(
  prep: Extract<SoundPrep, { kind: "ready" }>,
  pop: readonly string[],
  popRan: boolean,
  popOk: boolean,
  played: ChainOutcome,
  target: SystemTarget,
  probe: PlatformProbe,
): DeliverResult {
  // 弹窗没构造出来而声音还在跑：win32 的脚本缺失是**打包缺陷**，不能被「这次还有声音」盖掉
  // ——旧实现在这一格是无条件出声的。
  if (!popRan && toastScriptMissing(probe)) target.logger.warn(toastScriptMissingWarn(target));
  // 弹窗命令非空说明工具确实在：它的非零退出是真失败，不再是「无桌面会话」那类常态环境
  // （后者走的是 `!notifySendAvailable`，命令根本构造不出来）。
  if (!popOk) return failed("reasonSystemPopupFailed", { bin: commandNameOf(pop) });
  // 声音只在它是本次唯一动作时才翻转终态；toast 已经出去时声音是尽力而为。
  if (!played.ok && !popRan) {
    return failed("reasonSystemSoundFailed", { bin: chainBin(prep.commands) }, played.detail);
  }
  return delivered();
}

/**
 * 弹窗与提示音是两个独立动作，但**终态只有一个**：执行过动作而它失败了就翻转终态，一条命令都
 * 构造不出来才是空动作。弹窗场景下自播失败不改终态——toast 已经出去了，声音是尽力而为。
 */
export async function sendSystem(
  target: SystemTarget,
  message: NotifyMessage,
): Promise<DeliverResult> {
  // 弹窗与提示音都关：投递发生过，但本次没有可执行的动作——「要不要投递」在管线（只看 `enabled`），
  // 这里是本出口对「发什么」的回答，所以不弹不响不该被记成一次投递成功。早退顺带省掉一次平台探测。
  // 不留 warn：这是用户显式写下的意图，不是环境没能力；成因经 code 带出去，别把日志刷成噪声。
  if (!target.popup && target.sound === false) {
    return { status: "skipped", reason: reason("reasonSkipConfig") };
  }
  const probe = await platformCapabilities.get(target.toastScript, probePlatform);
  const selfPlay = shouldSelfPlay(target.popup, target.sound, probe.platform);
  const prep = selfPlay ? prepareSound(probe, toneOf(target.sound)) : NO_SOUND;

  if (!target.popup) return runSoundOnly(prep, target, probe);

  const pop = buildSystemCommand(
    probe,
    truncateCodePoints(message.title, displayCaps.system.titleMax),
    truncateCodePoints(message.body, displayCaps.system.bodyMax),
    { sound: target.sound, selfPlay, toastScript: target.toastScript },
  );
  // 两条都跑：弹窗失败不该顺手把声音也丢掉（用户至少还能听见）。顺序是先弹后响。
  const popRan = pop.length > 0;
  const popOk = popRan ? await runCommand(pop, target.logger) : true;

  // 本次没有可执行的播放命令：临时目录写不进去，或素材 / 候选播放器一个都没有。
  if (prep.kind !== "ready") {
    return handleUnreadyPrepWithPopup(prep, pop, popRan, popOk, target, probe);
  }

  const played = await playChain(prep, target);
  return finishPopupWithSound(prep, pop, popRan, popOk, played, target, probe);
}

/** 跑回退链：素材一定就绪（`prep.kind === "ready"`），临时文件在链尾结算后交还给 `finally` 收走。 */
async function playChain(
  prep: Extract<SoundPrep, { kind: "ready" }>,
  target: SystemTarget,
): Promise<ChainOutcome> {
  try {
    return await runSoundChain(prep.commands, target.logger);
  } finally {
    // unstage 必须晚于最后一次 run() 的 onExit：链已经 await 完，播放器手里的 inode 也已经打开过；
    // 反过来（spawn 后立即 unlink）实测播放器会报 42B 的「打不开」。
    if (prep.staged !== undefined) unstageToneAudio(prep.staged);
  }
}

/**
 * 空动作的收口：本次没有可执行的动作，留**恰好一条** warn。旧实现把这条 warn 硬编码在 win32
 * 分支上，于是 linux / darwin 的同一格完全静默——「推成功却没声音」的最直接来源。
 */
function unexecutable(target: SystemTarget, probe: PlatformProbe): DeliverResult {
  target.logger.warn(
    toastScriptMissing(probe)
      ? toastScriptMissingWarn(target)
      : `dsh-notifier: 系统频道没有可执行的动作，通知未发出（平台 ${probe.platform}）`,
  );
  // 成因分两种：脚本缺失是插件自己的打包缺陷，其余是宿主环境没能力。两者都不该被当成
  // 「用户自己关的」，但让它们共用一个 code 会把打包缺陷说成环境问题，故分开。
  return {
    status: "skipped",
    reason: reason(
      toastScriptMissing(probe) ? "reasonSystemToastScriptMissing" : "reasonSkipEnvironment",
    ),
  };
}

/** 临时文件写不进去的空动作收口：终态 `skipped`（没有任何可执行的动作），成因走新 code。 */
function unwritableSound(target: SystemTarget, cause: string): DeliverResult {
  target.logger.warn(toneUnwritableWarn(cause));
  return {
    status: "skipped",
    reason: reason("reasonSystemToneUnwritable", { detail: cause }),
  };
}

/** 临时目录写不进去的告警文案：原因（EROFS / EACCES 原文）要带上，否则只知道「没声音」。 */
function toneUnwritableWarn(cause: string): string {
  return `dsh-notifier: 系统提示音临时文件写入失败，本次未发声：${cause}`;
}

/** win32 的 toast 脚本不在：命令根本构造不出来。它是打包缺陷，不是用户的桌面环境问题。 */
function toastScriptMissing(probe: PlatformProbe): boolean {
  return probe.platform === "win32" && !probe.toastScriptAvailable;
}

/** 打包缺陷的告警文案：要指向那个文件，否则「弹窗没出来」无从查起。 */
function toastScriptMissingWarn(target: SystemTarget): string {
  return `dsh-notifier: 系统通知脚本缺失，Windows 弹窗未发出：${target.toastScript}`;
}

/** 全失败时的 `params.bin`：回退链上第一个候选（表序最靠前的命中者）。 */
function chainBin(commands: readonly ToneCommand[]): string {
  const first = commands[0];
  return first === undefined ? "unknown" : commandNameOf(first.command);
}

/** 命令的 bin 名：失败理由带上它，设置页才看得出是哪条命令没跑成。 */
function commandNameOf(command: readonly string[]): string {
  return command[0] ?? "unknown";
}

/** 声音选择 → 自播目标音色（true = 各平台的跟随系统默认音）。 */
function toneOf(sound: ToneSetting): string {
  return typeof sound === "string" ? sound : FOLLOW_SYSTEM_TONE;
}

/** 成功结果：两个分支共用同一形状。 */
function delivered(): DeliverResult {
  return { status: "ok", stage: "delivered" };
}

/**
 * 失败结果：有失败证据就必须翻转终态。不可重试——平台能力与命令退出码不会因为重投而改变，
 * 换一次投递还是同样的结论。`detail` 放各候选的成因摘要（宿主原文口径），设置页折叠可查。
 */
function failed(code: ReasonCode, params?: ReasonParams, detail?: string): DeliverResult {
  const extra: { params?: ReasonParams; detail?: string } = {};
  if (params !== undefined) extra.params = params;
  if (detail !== undefined && detail !== "") extra.detail = detail;
  return {
    status: "failed",
    stage: "delivered",
    reason: reason(code, extra),
    retryable: false,
  };
}

/**
 * dsh-notifier channels 域 system 块 —— Linux 自播播放器的事实表与运行期判据。
 *
 * 为什么是表：链序（先试哪个播放器）不是散在 `sendSystem` 里的分支串，而是这张表的**行序**；
 * 新增播放器 = 加一行，改序 = 挪一行。探测参数、命令行、能力面判据（`needsServer`）与运行期
 * 判据（`fatalMarkers`）都从同一行读，不再有第二份名单。
 *
 * 运行期判据为什么不是「stderr 必须为空」：本机实测（Ubuntu 22.04 / ffplay 4.4.2-0ubuntu0.22.04.1 /
 * 2026-09-14）40 次成功播放里有 **3 次** stderr 非空——libasound 直写
 * `ALSA lib pcm.c:8568:(snd_pcm_recover) underrun occurred`，且不受 `-loglevel` 约束（换
 * `-loglevel quiet` 再跑 30 次仍有 2 次）。真成功会被判失败 ⇒ 链继续 ⇒ 双响，或终态 `failed`
 * 而声音其实已经出去了。判据因此是「退出码 + 实测致命标记」。
 */
import type { CommandFacts } from "./type.ts";

/** 播放器候选：一行数据就是它在链上的全部事实。 */
export interface PlayerSpec {
  readonly bin: string;
  /** 探测参数：**任一**成功即命中（各播放器的版本参数不统一，实测 ffplay 的 `--version` exit 1）。 */
  readonly probeArgs: readonly (readonly string[])[];
  /** 播放一条音频文件的参数（文件名由调用方接在最后，仍是参数数组，不经 shell）。 */
  readonly fileArgs: (file: string) => readonly string[];
  /** 无声音服务时必失败：能力面据此把「只命中服务型候选」判成 degraded 而不是 ok。 */
  readonly needsServer: boolean;
  /** 命中即判失败的 stderr 标记（判据用；只收实测样本，见下方常量）。 */
  readonly fatalMarkers: readonly string[];
}

/**
 * 实测致命标记表（每条都能指到本机样本，2026-09-14 / Ubuntu 22.04 / ffplay 4.4.2）：
 * `Failed to open file … or configure filtergraph`（输入打不开）、`audio open failed`
 * （`No more combinations to try, audio open failed`）、`Could not initialize SDL`
 * （`SDL_AUDIODRIVER=nonexistent`）、`Failed to create window or renderer`（缺 `-nodisp`）、
 * `No such file or directory`（文件不存在）、`Invalid data found when processing input`（空文件/
 * 随机字节）、`Is a directory`（目录当输入）。
 *
 * **不在表里**的是已知噪声：以 `ALSA lib ` 开头的行在成功路径上也会出现（3/40）。这一条正是
 * 「零输出」判据被推翻的地方——把输出本身当失败证据，就会把真成功判成失败。
 *
 * 表按行共享给链上每个候选：表里全是**失败文本**，命中它只可能把一次假成功翻成失败（本判据的
 * fail-open 残余要收的正是这个），不会反过来误杀成功；而 `aplay`/`paplay`/`pw-play` 的失败
 * 文本本机没有样本，按「未实测面结构性隔离」一条都不写——表里只有实测过的字符串。
 */
const FATAL_MARKERS: readonly string[] = [
  "Failed to open file",
  "audio open failed",
  "Could not initialize SDL",
  "Failed to create window or renderer",
  "No such file or directory",
  "Invalid data found when processing input",
  "Is a directory",
];

/**
 * Linux 自播回退链（维护者裁决的链序 = 本表行序）：
 * `paplay` → `pw-play` → `aplay` → `ffplay`（先服务型、再直接怼 ALSA 的轻量播放器、
 * 最后 ffplay——它最不挑环境但最重）。
 */
export const LINUX_PLAYERS: readonly PlayerSpec[] = [
  {
    bin: "paplay",
    // 未实测（本机无 paplay）：`--version` 是 PulseAudio 系 CLI 的通行参数
    probeArgs: [["--version"]],
    fileArgs: (file) => [file],
    needsServer: true,
    fatalMarkers: FATAL_MARKERS,
  },
  {
    bin: "pw-play",
    // 未实测（本机无 pw-play）：PipeWire 自带的 PA 兼容 CLI，版本参数与 paplay 同形
    probeArgs: [["--version"]],
    fileArgs: (file) => [file],
    needsServer: true,
    fatalMarkers: FATAL_MARKERS,
  },
  {
    bin: "aplay",
    // 未实测（本机无 aplay）：ALSA 自带 CLI，`--version` 是它的通行参数
    probeArgs: [["--version"]],
    fileArgs: (file) => [file],
    needsServer: false,
    fatalMarkers: FATAL_MARKERS,
  },
  {
    bin: "ffplay",
    // 实测：`ffplay --version` **exit 1**（它只认单横线的 `-version`），故两个参数都试
    probeArgs: [["-version"], ["-h"]],
    // 四个参数都必需：`-hide_banner`/`-loglevel error` 压噪声，`-nodisp` 禁开窗口
    // （缺它实测 exit 0 但只报 `Failed to create window or renderer`，根本不出声），
    // `-autoexit` 播完即退（缺它进程不退出，只能等 8 秒兜底杀）
    fileArgs: (file) => ["-hide_banner", "-loglevel", "error", "-nodisp", "-autoexit", file],
    needsServer: false,
    fatalMarkers: FATAL_MARKERS,
  },
];

/** 按 bin 取表行：命中的播放器名是探测产出，命令行与判据都要回到表上。 */
export function playerSpec(bin: string): PlayerSpec | undefined {
  return LINUX_PLAYERS.find((player) => player.bin === bin);
}

/** 判据结论：命令的原始结局，或「退出码 0 却命中了致命标记」——两者都是失败成因。 */
export type PlayFailure =
  | { readonly kind: "exit"; readonly code: number }
  | { readonly kind: "killed" }
  | { readonly kind: "timeout" }
  | { readonly kind: "spawn-threw"; readonly cause: string }
  | { readonly kind: "spawn-error"; readonly cause: string }
  | { readonly kind: "marker"; readonly marker: string };

/**
 * 音频路径的具名判据：`exit≠0` / 被信号杀死 / 超时兜底 / 启动失败 / 命中实测致命标记 ⇒ 失败，
 * 其余 ⇒ 成功。`spec === undefined` 表示这条命令不在播放器表上（darwin 的 `afplay`、win32 的
 * PowerShell），此时**只判退出码**——ffplay 上量到的标记不是它们的成败语义。
 */
export function playFailure(
  spec: PlayerSpec | undefined,
  facts: CommandFacts,
): PlayFailure | undefined {
  const outcome = facts.outcome;
  if (outcome.kind !== "exit") return outcome;
  if (outcome.code !== 0) return outcome;
  if (spec === undefined) return undefined;
  const marker = spec.fatalMarkers.find((item) => facts.stderr.includes(item));
  return marker === undefined ? undefined : { kind: "marker", marker };
}

/**
 * 这次失败要不要在日志里出声：被信号杀死多数是我们自己的超时兜底（主动行为），按异常刷屏会淹掉
 * 真失败；超时兜底是例外——那一格旧实现零日志零结算，必须留痕（见 `run` 的兜底杀进程）。
 */
export function warnWorthy(failure: PlayFailure): boolean {
  return failure.kind !== "killed";
}

/** 一个候选失败的可读摘要（进 warn，也进 `reason.detail`）：`bin 成因`。 */
export function playFailureSummary(bin: string, failure: PlayFailure, tail: string): string {
  const suffix = tail === "" ? "" : `：${tail}`;
  switch (failure.kind) {
    case "exit":
      return `${bin} 退出码 ${failure.code}${suffix}`;
    case "killed":
      return `${bin} 被信号杀死${suffix}`;
    case "timeout":
      return `${bin} 超时未退出${suffix}`;
    case "spawn-threw":
      return `${bin} 启动失败：${failure.cause}`;
    case "spawn-error":
      return `${bin} 不可用：${failure.cause}`;
    case "marker":
      return `${bin} 命中致命标记「${failure.marker}」${suffix}`;
  }
}

/**
 * dsh-notifier channels 域 —— 自包含提示音的 WAV 合成（#783）。
 *
 * 为什么在运行时合成、不随包附音频资产：现状的声音依赖发行版的
 * `sound-theme-freedesktop`（实测无头宿主上该目录**不存在** ⇒ 一点声音都没有，而宿主明明
 * 有 ALSA 播放设备），随包附 wav 则会把音频二进制带进 git、且「音色」设置事实上退化成
 * 同一个声。合成只需要几十行 RIFF/PCM，零依赖。
 *
 * 音符序列不在这里：音色事实收在 `shared/interface.ts`，与客户端试听/自播共用同一段
 * `notes`——本文件只负责把它渲染成采样，否则「试听是什么音、宿主放出来是什么音」会再次分叉。
 */
import { TONES } from "../../../../shared/interface.ts";
import type { ToneNote } from "../../../../shared/interface.ts";

/** 采样率取 44.1 kHz：ALSA 与 SDL 的默认路径都原生支持，避免重采样引入的额外依赖。 */
const SAMPLE_RATE = 44100;
/** 位深与声道固定 16-bit 单声道：提示音不需要立体声，单声道体积减半。 */
const BITS_PER_SAMPLE = 16;
const CHANNELS = 1;
/** 首尾淡入淡出时长：消除播放两端的咔嗒声。 */
const FADE_MS = 8;
/** 振幅取满量程的 45%：提示音不该是刺耳的最大音量（听感由宿主音量控制）。 */
const AMPLITUDE = 0.45;

/**
 * 合成指定音色的 WAV 字节。
 *
 * 未知音色返回 null（**不猜一个默认音顶替**，与 `toneFileCandidates` 的候选同口径）：
 * 静默比放错音更容易被发现，也更诚实。
 */
export function synthToneWav(tone: string): Buffer | null {
  // 跨边界值不受编译期约束：原型链键名（`constructor` / `__proto__` / `hasOwnProperty`）
  // 不是 TONES 的成员，`in` 与直接取值都会读到 Object.prototype 上的成员而非音色。
  if (!Object.hasOwn(TONES, tone)) return null;
  const notes = TONES[tone].notes;
  if (notes.length === 0) return null;
  return encodeWav(renderSamples(notes));
}

/**
 * 把音符序列渲染成 16-bit PCM 采样。
 *
 * 总长取最晚结束的音符：`at` 留下的间隙必须是**真静音**（保持 0），把音符首尾相接会让
 * 客户端听上去有停顿、宿主上却没有。
 *
 * 时间上重叠的音符按采样**相加**而不是后者覆盖：客户端的 Web Audio 是多个振荡器同时响，
 * 覆盖会让重叠区只剩后一个音，于是同一份 notes 在两端听出两种旋律。
 */
function renderSamples(notes: readonly ToneNote[]): Int16Array {
  const startOf = (note: ToneNote): number => Math.round(note.at * SAMPLE_RATE);
  const lengthOf = (note: ToneNote): number => Math.round(note.dur * SAMPLE_RATE);
  const total = notes.reduce((end, note) => Math.max(end, startOf(note) + lengthOf(note)), 0);
  const mix = new Float64Array(total);
  for (const note of notes) {
    const start = startOf(note);
    const span = lengthOf(note);
    const fade = Math.min(Math.round((FADE_MS / 1000) * SAMPLE_RATE), Math.floor(span / 2));
    for (let i = 0; i < span && start + i < total; i += 1) {
      const phase = (i * note.freq) / SAMPLE_RATE;
      const wave = note.type === "triangle" ? triangleAt(phase) : Math.sin(2 * Math.PI * phase);
      mix[start + i] += wave * fadeEnvelope(i, span, fade) * AMPLITUDE;
    }
  }
  const samples = new Int16Array(total);
  for (let i = 0; i < total; i += 1) samples[i] = Math.round(mix[i] * 0x7fff);
  return samples;
}

/** 三角波：与客户端 Web Audio 的 `triangle` 同形（相位 0 起于 0，1/4 周期到峰）。 */
function triangleAt(phase: number): number {
  const p = phase - Math.floor(phase);
  if (p < 0.25) return 4 * p;
  if (p < 0.75) return 2 - 4 * p;
  return 4 * p - 4;
}

/** 首尾线性淡入淡出；`fade = 0`（极短音符）时退化为恒定包络，避免除零。 */
function fadeEnvelope(index: number, count: number, fade: number): number {
  if (fade <= 0) return 1;
  if (index < fade) return index / fade;
  const tailStart = count - fade;
  if (index >= tailStart) return (count - index) / fade;
  return 1;
}

/**
 * 44 字节 RIFF/WAVE 头 + PCM 数据（单声道 16-bit，无扩展块）。
 *
 * 采样率不再作参数：它由本模块的常量决定，收成参数只是把「唯一取值」伪装成可配置，
 * 而多一条调用路径就多一处可以传错的地方。
 */
function encodeWav(samples: Int16Array): Buffer {
  const dataBytes = samples.length * (BITS_PER_SAMPLE / 8);
  const buffer = Buffer.alloc(44 + dataBytes);
  const byteRate = SAMPLE_RATE * CHANNELS * (BITS_PER_SAMPLE / 8);
  buffer.write("RIFF", 0, "ascii");
  buffer.writeUInt32LE(36 + dataBytes, 4);
  buffer.write("WAVE", 8, "ascii");
  buffer.write("fmt ", 12, "ascii");
  buffer.writeUInt32LE(16, 16); // fmt 块长度：PCM 固定 16
  buffer.writeUInt16LE(1, 20); // 1 = PCM（未压缩）
  buffer.writeUInt16LE(CHANNELS, 22);
  buffer.writeUInt32LE(SAMPLE_RATE, 24);
  buffer.writeUInt32LE(byteRate, 28);
  buffer.writeUInt16LE(CHANNELS * (BITS_PER_SAMPLE / 8), 32); // 块对齐
  buffer.writeUInt16LE(BITS_PER_SAMPLE, 34);
  buffer.write("data", 36, "ascii");
  buffer.writeUInt32LE(dataBytes, 40);
  for (let i = 0; i < samples.length; i += 1) buffer.writeInt16LE(samples[i], 44 + i * 2);
  return buffer;
}

/**
 * dsh-notifier channels 域 system 块 —— 自播素材的来源与生命周期。
 *
 * 这里只回答「本次播什么、什么时候收」：素材是宿主的主题文件还是运行时合成的一段 WAV，临时文件
 * 何时落盘、何时 unlink、何时连目录一起释放。播放器知识与命令行构造不在这里（归 `players.ts` 与
 * `index.ts`），文件系统原语也不在这里（归 `deps.ts` 的进程事实端口）。
 */
import { systemDeps } from "./deps.ts";
import { synthToneWav } from "./synth.ts";
import { toneFileCandidates } from "./tones.ts";
import type { ToneStage } from "./type.ts";

/** 本次自播的素材：宿主主题文件优先，缺失时才走运行时合成。 */
export type ToneSource =
  | { readonly kind: "theme"; readonly path: string }
  | { readonly kind: "synth"; readonly bytes: Buffer }
  | { readonly kind: "none" };

/**
 * 主题文件优先：宿主装了 `sound-theme-freedesktop` 时仍用它调过的素材（合成音只是无头宿主的兜底，
 * 不是替换品）。只有候选**全部**不存在时才落合成音，且只对 Linux 合成——darwin/win32 有系统自带
 * 素材与播放器，合成兜底解决的正是 #783 的无头 Linux 现场。
 */
export function resolveToneSource(platform: string, tone: string): ToneSource {
  const deps = systemDeps();
  const theme = toneFileCandidates(platform, tone).find((path) => deps.existsSync(path));
  if (theme !== undefined) return { kind: "theme", path: theme };
  if (platform !== "linux") return { kind: "none" };
  const bytes = synthToneWav(tone);
  return bytes === null ? { kind: "none" } : { kind: "synth", bytes };
}

/** 把合成音落到临时文件：失败（`/tmp` 只读挂载）时本次**没有可执行的播放动作**。 */
export function stageToneSource(bytes: Buffer): ToneStage {
  return systemDeps().stageToneAudio(bytes);
}

/**
 * 删掉本次的临时音频文件。**只删这一个文件**，目录留到释放面：按次删目录会让并发投递里先完成的
 * 那一笔把另一笔正在播的文件一起收走（实测的失败形态是播放器报 42B 的「打不开」）。
 */
export function unstageToneAudio(path: string): void {
  systemDeps().unstageToneAudio(path);
}

/**
 * 释放音频临时目录（通道域的释放面）：组合根在卸载时调一次，端口侧在进程退出时也挂一次。
 * 幂等、**never-throw**——卸载链上一个出口失败不该拖垮其余释放动作。
 */
export function releaseSoundTemps(): void {
  systemDeps().releaseToneTemps();
}

/**
 * dsh-notifier channels 域 —— 音色到平台素材文件的翻译。
 *
 * 表是数据不是决策：本文件只回答「这个平台上这个音色的候选文件是哪几个」，不认识
 * 「用户能选哪些音色」。音色事实本身（含三个平台的素材字段）收在 `shared/interface.ts`，
 * 本文件不再持有第二份表——两份表已实测漂移过（#783）。
 */
import { posix as pathPosix, win32 as pathWin } from "node:path";

import { TONES } from "../../../../shared/interface.ts";

/** 平台声音文件基目录（命令只在此目录内拼绝对路径）。 */
const TONE_BASE_DIRS: Readonly<Record<string, string>> = {
  linux: "/usr/share/sounds/freedesktop/stereo",
  darwin: "/System/Library/Sounds",
  win32: "C:\\Windows\\Media",
};

/** 平台 × 音色 → 候选文件绝对路径（首存在者胜）。 */
export function toneFileCandidates(platform: string, tone: string): readonly string[] {
  const base = TONE_BASE_DIRS[platform];
  if (base === undefined) return [];
  // win32 按 win32 语义拼：反斜杠是那条命令骨架的一部分
  const join = platform === "win32" ? pathWin.join : pathPosix.join;
  return candidateNames(platform, tone).map((name) => join(base, name));
}

/** 未知音色给不出候选（跨边界值不受编译期约束）：不猜一个默认音顶替。 */
function candidateNames(platform: string, tone: string): readonly string[] {
  // `constructor` / `__proto__` 这类原型链键名不是 TONES 的成员，直接取值会读到
  // Object.prototype 上的东西，于是给出一个并不存在的候选路径。`in` 有同样的坑。
  if (!Object.hasOwn(TONES, tone)) return [];
  const spec = TONES[tone];
  if (platform === "linux") return spec.linuxFile ?? [];
  if (platform === "darwin")
    return spec.darwinSound === undefined ? [] : [`${spec.darwinSound}.aiff`];
  if (platform === "win32") return spec.win32File ?? [];
  return [];
}

/**
 * dsh-notifier channels 域 —— webhook 出口。
 * 模板走两步法防注入：先替换裸值 {{ts}}、JSON.parse 整份模板，再对字符串值做占位符替换
 * 后重新序列化，替换内容因此逃不出字符串。任何失败都不重试。
 */
// 默认模板与 {{priority}} 映射表的事实源在 src/shared/webhooks.ts（两端共享面）：客户端「恢复
// 默认模板」与本出口渲染读同一份字面量——两处各写一份时的漂移症状是「设置页看到的模板与实际发
// 出去的 body 不是同一份」。命名差异（配置层 custom = 投递层 raw）也在那里单点化。
import { WEBHOOK_DEFAULT_TEMPLATES, WEBHOOK_PRIORITY } from "../../../../shared/interface.ts";
import type { ReasonCode, ReasonParams } from "../../../shared/interface.ts";
import { clampReasonDetail, reason } from "../../../shared/interface.ts";
import {
  FAILURE_REASON_MAX,
  RESPONSE_DETAIL_MAX,
  displayCaps,
  truncateCodePoints,
} from "../deliver/caps.ts";
import type {
  DeliverResult,
  HttpFetch,
  HttpFetchResult,
  NotifyMessage,
  NotifySeverity,
} from "../deliver/type.ts";
import type {
  WebhookPreset,
  WebhookRenderVars,
  WebhookTarget,
  WebhookTemplateNode,
} from "./type.ts";

/** 投递超时边界与缺省（秒），与配置层同一口径。 */
const MIN_TIMEOUT_SEC = 1;
const MAX_TIMEOUT_SEC = 60;
const DEFAULT_TIMEOUT_SEC = 10;

/** 占位符（`{{ts}}` 不在其中：它只在文本层替换，见 renderWebhookBody）。 */
const TOKEN_RE = /\{\{\s*(title|message|kind|severity|priority|source)\s*\}\}/g;

/** `{{priority}}` 渲染值；severity 非法（跨边界值不受编译期约束）视同未提供。 */
export function priorityFor(preset: WebhookPreset, severity?: NotifySeverity): string {
  const mapped =
    severity !== undefined && Object.hasOwn(WEBHOOK_PRIORITY[preset], severity)
      ? WEBHOOK_PRIORITY[preset][severity]
      : undefined;
  if (mapped !== undefined) return mapped;
  return preset === "raw" ? "" : WEBHOOK_PRIORITY[preset].info;
}

/** 渲染 body；模板非法 JSON 即抛错（调用方转成这次投递失败，绝不降级成文本发送）。 */
export function renderWebhookBody(
  template: string,
  preset: WebhookPreset,
  vars: WebhookRenderVars,
): string {
  const source = template.length > 0 ? template : WEBHOOK_DEFAULT_TEMPLATES[preset];
  // 第一步：只有 {{ts}} 允许裸值形态（数字直出），否则模板不可能通过 JSON.parse
  const step1 = source.split("{{ts}}").join(String(Math.round(vars.ts)));
  let tree: WebhookTemplateNode;
  try {
    tree = JSON.parse(step1) as WebhookTemplateNode;
  } catch (cause) {
    const reason = cause instanceof Error ? cause.message : String(cause);
    throw new Error(`webhook 模板不是合法 JSON: ${reason}`);
  }
  // 第二、三步：只替换字符串值；重新序列化时统一转义，注入内容逃不出这个字符串
  return JSON.stringify(
    renderTree(tree, {
      title: vars.title,
      message: vars.message,
      kind: vars.kind,
      severity: vars.severity ?? "",
      priority: priorityFor(preset, vars.severity),
      source: "",
    }),
  );
}

/** 遍历模板树，单趟替换字符串值里的占位符（替换内容不会被再次扫描）。 */
function renderTree(
  node: WebhookTemplateNode,
  values: Readonly<Record<string, string>>,
): WebhookTemplateNode {
  if (typeof node === "string") {
    return node.replace(TOKEN_RE, (match, name: string) =>
      Object.hasOwn(values, name) ? values[name] : match,
    );
  }
  if (Array.isArray(node)) return node.map((item) => renderTree(item, values));
  if (typeof node === "object" && node !== null) {
    const rebuilt: Record<string, WebhookTemplateNode> = {};
    for (const [key, value] of Object.entries(node)) rebuilt[key] = renderTree(value, values);
    return rebuilt;
  }
  return node;
}

/**
 * 默认出站实现：全局 fetch。已保存路径的语义锚点——调用方不传第三个参数时走这里，
 * 与重写前逐字一致；dry-run 传自己的 SSRF 安全实现（见 bark 出口同款注释）。
 */
const defaultFetch: HttpFetch = (url, init) => globalThis.fetch(url, init);

/** 请求体由模板渲染；任何失败都不重试（模板或凭据写错，重投三次还是同样的结论）。 */
export async function sendWebhook(
  target: WebhookTarget,
  message: NotifyMessage,
  fetchImpl: HttpFetch = defaultFetch,
): Promise<DeliverResult> {
  let body: string;
  try {
    // 空模板由 renderWebhookBody 回落到 preset 默认模板
    body = renderWebhookBody(target.template ?? "", target.preset, {
      title: truncateCodePoints(message.title, displayCaps.webhook.titleMax),
      message: truncateCodePoints(message.body, displayCaps.webhook.bodyMax),
      kind: message.kind,
      severity: message.severity,
      ts: message.ts,
    });
  } catch (cause) {
    const detail = cause instanceof Error ? cause.message : String(cause);
    return failed("reasonWebhookTemplateInvalid", { detail });
  }

  const headers: Record<string, string> = { ...target.headers };
  setHeader(headers, "content-type", "application/json; charset=utf-8");
  const auth = target.auth;
  // 枚举之外的认证方式（跨边界值）一律不套用：凭据只走请求头，拼进 URL 会留在对端访问日志里。
  if (auth !== undefined) {
    if (auth.kind === "bearer") {
      setHeader(headers, "authorization", `Bearer ${auth.token}`);
    } else if (auth.kind === "basic") {
      const pair = Buffer.from(`${auth.user}:${auth.password}`).toString("base64");
      setHeader(headers, "authorization", `Basic ${pair}`);
    }
  }

  let response: HttpFetchResult;
  try {
    response = await fetchImpl(target.url, {
      method: "POST",
      headers,
      body,
      signal: AbortSignal.timeout(clampTimeoutSec(target.timeoutSec) * 1000),
    });
  } catch (cause) {
    const detail = cause instanceof Error ? cause.message : String(cause);
    return failed("reasonWebhookRequestFailed", { detail });
  }
  if (!response.ok) {
    let detail = "";
    try {
      detail = truncateCodePoints(await response.text(), RESPONSE_DETAIL_MAX);
    } catch {
      // 读不到响应体：状态码本身已是完整原因
    }
    return failed("reasonWebhookHttp", { params: { status: response.status }, detail });
  }
  return { status: "ok", stage: "delivered" };
}

/**
 * 写固定头：先摘掉同名（大小写不敏感）的自定义头——fetch 的 Headers 会把同名两键合并
 * 成一个值，凭据与 content-type 都会被发成两份。
 */
function setHeader(headers: Record<string, string>, name: string, value: string): void {
  for (const key of Object.keys(headers)) {
    if (key.toLowerCase() === name) delete headers[key];
  }
  headers[name] = value;
}

/**
 * 投递超时 clamp 到 1..60 秒（缺省 10）：配置层已归一，这里兜跨边界值。
 *
 * 导出是为了让这条口径可表驱动：clamp 的产物只落在 `AbortSignal` 的 deadline 上，从外面读不出来
 * ——「上界被改宽」与「下界被改成 0」在行为用例里都是绿的。
 */
export function clampTimeoutSec(value?: number): number {
  if (typeof value !== "number" || !Number.isFinite(value)) return DEFAULT_TIMEOUT_SEC;
  return Math.min(MAX_TIMEOUT_SEC, Math.max(MIN_TIMEOUT_SEC, Math.round(value)));
}

/** 失败结果：code 出文案、detail 存宿主原文；截断是展示语义，不是脱敏。 */
function failed(
  code: ReasonCode,
  options: { readonly params?: ReasonParams; readonly detail?: string } = {},
): DeliverResult {
  return {
    status: "failed",
    stage: "delivered",
    reason: clampReasonDetail(reason(code, options), FAILURE_REASON_MAX),
    // 零重试是硬约束：失败即终态，交回管线也没有第二次
    retryable: false,
  };
}

