/**
 * dsh-notifier —— 频道对外 id 的归一化（纯数据 + 纯判定，无 import）。
 *
 * 为什么两端共用一份：id 是客户端勾选（写进 `kindRoutes`）与宿主端路由（投递池里的 `channelId`）
 * 之间唯一的对齐键。两端各算一份时漂移的症状是「用户勾了频道却收不到」——客户端写进去的字符串
 * 在投递池里找不到，通知静默落回广播或整个丢掉，而两边的代码各自看起来都对。
 *
 * 规则：内置频道取裸 `type`（身份由 `type` 唯一确定，不存在实例 id），实例频道取 `type:id`。
 * 两个集合天然不相交：内置的裸 id 永远不含冒号。
 */

/** 内置频道（值即 id）。 */
export const BUILTIN_CHANNELS = { browser: "browser", system: "system" } as const;

/**
 * 内置频道类型（顺序即设置页卡片顺序）。
 *
 * 与 `BUILTIN_CHANNELS` 的键集必须逐项相等：后者是客户端「是不是内置频道」内联判定的由来，
 * 前者是宿主端内置清单的由来。`satisfies` 只保证这一侧 ⊆ 那一侧，反向相等由
 * test/unit/shared/channels.test.ts 双向断言钉住。
 */
export const BUILTIN_CHANNEL_TYPES = [
  "browser",
  "system",
] as const satisfies readonly (keyof typeof BUILTIN_CHANNELS)[];

/** 内置频道类型。 */
export type BuiltinChannelType = (typeof BUILTIN_CHANNEL_TYPES)[number];

/** 运行时成员判定：编译期联合约束不到跨边界传来的值。 */
export function isBuiltinChannelType(value: unknown): value is BuiltinChannelType {
  return typeof value === "string" && (BUILTIN_CHANNEL_TYPES as readonly string[]).includes(value);
}

/**
 * 实例频道 id：`type:id`。
 *
 * 参数刻意用窄类型（`unknown`）而不是宿主端的 `ChannelConfig`：那会把宿主类型拖进跨端面，
 * 而这里只做字符串拼接。空类型 / 空 id 归一成空串——脏配置不该产出 `undefined:undefined`
 * 这种会被当成合法 id 记账的字符串。
 */
export function channelIdFor(channel: { readonly type?: unknown; readonly id?: unknown }): string {
  return String(channel.type || "") + ":" + String(channel.id || "");
}

/** 频道对外 id：内置取裸 `type`，实例取 `type:id`。 */
export function channelIdOf(channel: { readonly type?: unknown; readonly id?: unknown }): string {
  const type = String(channel.type || "");
  return isBuiltinChannelType(type) ? type : channelIdFor(channel);
}

packages/dsh-notifier/src/shared/dispose.source:
/**
 * dsh-notifier —— 两端共享的「清理栈」。
 *
 * 为什么做成共享面：宿主端 assemble() 与客户端 apply() 是同一件事的两半——按依赖顺序建立资源、
 * 卸载时全部释放。两边各写一份「收集 + 逆序吞错释放」的实现，就一定会有一处先腐烂（宿主端原先
 * 那份私有 safeDisposeAll 就是第一份，客户端此前甚至是正序、且一条抛错就跳过其余）。
 *
 * 为什么 attach 要写在 finally 里（而不是「构造时就登记」）：cordis 按 LIFO 释放同一 fiber 上的
 * effect。宿主端一旦把本栈的 effect 登记在服务 provisioning 之前，整条栈就会在「服务面已撤」之后
 * 才释放各域——api 域在别人已放开的入参上继续服务（real-context 的「卸载逆序」判据实测判红）。
 * 所以登记点必须留在采集之后；而 finally 保证装配中途抛错时，已采集的 teardown 也有释放点。
 *
 * 零 import、零模块级可变状态（本目录参与两端打包：宿主经 tsc emit 后 esbuild 内联，客户端由
 * esbuild 直接解析 .ts）。
 */

/** 清理登记宿主：cordis ctx 的最小面，两端各用自己的那一个。 */
export interface DisposerHost {
  effect(callback: () => () => void, id: string): void;
}

export interface DisposerStack {
  /** 登记一处资源的清理动作（可在 attach 之前调用：采集与登记点是两件事）。 */
  own(teardown: () => void): void;
  /** 建立一处资源并当场登记它的清理；make 抛错则不留登记（资源没建成，就没有要释放的东西）。 */
  acquire<T>(make: () => T, release: (value: T) => void): T;
  /**
   * 登记 ctx.effect（整个生命周期只调用一次）。见文件头：调用点应在 finally 里。
   *
   * @param onError 单条清理抛错时的留痕出口；不传 = 保持宿主端「卸载阶段不上报」的既有语义。
   */
  attach(host: DisposerHost, id: string, onError?: (error: unknown) => void): void;
}

export function createDisposerStack(): DisposerStack {
  const teardowns: Array<() => void> = [];
  let attached = false;
  let released = false;
  let report: ((error: unknown) => void) | undefined;

  function run(teardown: () => void): void {
    try {
      teardown();
    } catch (error) {
      // 一个资源的清理失败不拖垮其余：卸载只发生一次，跳过其余等于永久残留。
      report?.(error);
    }
  }

  function release(): void {
    if (released) return;
    released = true;
    // 逆序（后获取的先释放）：后装的域可能依赖先装的域还活着。先 splice 再执行，
    // 于是重入（某条 teardown 里再触发释放）不会重复执行。
    for (const teardown of teardowns.splice(0).reverse()) run(teardown);
  }

  function enqueue(teardown: () => void): void {
    if (released) {
      // 释放之后再登记：资源是在作用域关闭后建立的，当场释放，不留成没人再看的残留。
      run(teardown);
      return;
    }
    teardowns.push(teardown);
  }

  return {
    own: enqueue,
    acquire(make, release2) {
      const value = make();
      enqueue(() => release2(value));
      return value;
    },
    attach(host, id, onError) {
      if (attached) {
        throw new Error(
          "createDisposerStack: attach 只能调用一次（重复登记会让先挂的那份永远不释放）",
        );
      }
      attached = true;
      report = onError;
      host.effect(() => () => release(), id);
    },
  };
}

packages/dsh-notifier/src/shared/kinds.t.source:
/**
 * dsh-notifier —— 通知类型表（纯数据 + 两个纯判定，无 import）。
 *
 * 为什么两端共用一份：内置 kind 的**事件开关键**与**展示强度**此前两端各写一份逐字相同的副本
 * （宿主端 judge 的 kind→开关键表、service 的 kind→强度表；客户端设置页的事件卡与历史行的
 * 开关键→kind、kind→强度）。漂移的症状是「事件色点 / 免打扰豁免与服务端裁决不是同一张表」：
 * 客户端认某个 kind 而宿主端不认，用户按下的开关就静默失效。
 *
 * 不搬进这里的是「开关键 → i18n 文案 key」那张表：文案属于客户端，宿主端没有翻译面。
 */
export const BUILTIN_KINDS = [
  "ask",
  "question",
  "done",
  "subagent-done",
  "error",
  "turn-end",
  "test",
] as const;

/** 内置通知种类。 */
export type BuiltinKind = (typeof BUILTIN_KINDS)[number];

/**
 * 外部注册的通知种类：`<命名空间>:<id>`。
 * 内置 kind 一律不含冒号，两个集合因此天然不相交；而白名单查询会在注册之前把没登记的
 * 种类误判成内置，误判方向恰好是放行。
 */
export type ExternalKind = `${string}:${string}`;

/** 通知种类：内置的，或外部注册的。 */
export type NotifyKind = BuiltinKind | ExternalKind;

/** 展示强度（severity 仅展示；过滤语义归 kind）。 */
export type NotifySeverity = "info" | "success" | "warning" | "failure";

/** 是不是内置种类。 */
export function isBuiltinKind(kind: string): kind is BuiltinKind {
  return (BUILTIN_KINDS as readonly string[]).includes(kind);
}

/**
 * 内置 kind → 缺省展示强度；外部 kind 没有缺省（强度由调用方自己说）。
 * 写成 `Record<BuiltinKind, …>`：新增一种内置通知时，漏配强度是编译错误。
 */
export const KIND_SEVERITY: Record<BuiltinKind, NotifySeverity> = {
  ask: "warning",
  question: "info",
  done: "success",
  "subagent-done": "info",
  error: "failure",
  "turn-end": "info",
  test: "info",
};

/** 合法强度全集的**运行时**形态（与 `NotifySeverity` 联合一一对应）。 */
export const NOTIFY_SEVERITIES = [
  "info",
  "success",
  "warning",
  "failure",
] as const satisfies readonly NotifySeverity[];

/** 运行时枚举校验：类型联合只在编译期存在，跨宿主边界传来的值不受它约束。 */
export function isNotifySeverity(value: string): value is NotifySeverity {
  return (NOTIFY_SEVERITIES as readonly string[]).includes(value);
}

/** 事件开关在设置里的键名（宿主端设置模型的字段名）。 */
export type KindSwitchKey =
  | "notifyAsk"
  | "notifyQuestion"
  | "notifyTaskDone"
  | "notifySubagentDone"
  | "notifyTaskError"
  | "notifyTurnEnd";

/**
 * 内置 kind → 事件开关键；`test` 不在表里——它不对应任何宿主事件，也就没有开关。
 *
 * 客户端设置页的那张逆向表（开关键 → kind）由本表**反转**得到，故这里是它的唯一事实源。
 * 表里的每个值都必须是设置模型里真实存在的布尔键：改名漏改一处会让开关读到一个恒 undefined
 * 的字段，症状是该事件的通知永远发不出。
 */
export const KIND_SWITCHES: Record<Exclude<BuiltinKind, "test">, KindSwitchKey> = {
  ask: "notifyAsk",
  question: "notifyQuestion",
  done: "notifyTaskDone",
  "subagent-done": "notifySubagentDone",
  error: "notifyTaskError",
  "turn-end": "notifyTurnEnd",
};

packages/dsh-notifier/src/shared/quiet.t.source:
/**
 * dsh-notifier —— 免打扰共享面（纯函数 + 纯数据，无 import，两端同源）。
 *
 * 为什么落在共享面：免打扰的「上限几个窗口」「HH:MM 长什么样」「某分钟落不落在窗口里」
 * 此前在三处各写一份（服务端裁决 judge、服务端输入闸门 input、客户端本机回显 events.tsx），
 * 口径一致全靠人工同步。改一边就是「页面回显命中、服务端不压制」这类两端各说各话。
 * 放进包内共享面，是为了让宿主端与浏览器端都不必 import 对方的实现文件。
 *
 * 约束（见 src/shared/interface.ts 头注）：本目录参与两端打包，故本文件零 import。
 */

/** 免打扰时间窗上限：写面超限 400 拒收（静默截断会让用户以为配好的时段生效了）。 */
export const QUIET_WINDOWS_LIMIT = 5;

/** `"HH:MM"` 二十四小时制（与输入闸门写面、归一化读面同一支正则的两面）。 */
const CLOCK_RE = /^([01]\d|2[0-3]):[0-5]\d$/;

/** 是否为合法时钟文本（写面与读面的形状闸门都走这里）。 */
export function isClockText(text: string): boolean {
  return CLOCK_RE.test(text);
}

/** `"HH:MM"` → 当日分钟数；形状非法或越界返回 NaN（脏设置不吃掉所有通知，见下）。 */
export function clockToMinutes(text: string): number {
  const match = /^(\d{2}):(\d{2})$/.exec(text);
  if (match === null) return NaN;
  const hours = Number(match[1]);
  const minutes = Number(match[2]);
  if (hours > 23 || minutes > 59) return NaN;
  return hours * 60 + minutes;
}

/**
 * 单个窗口是否命中（纯函数：只看分钟数与起止，不读当前时间，方便逐分钟单测）。
 * 支持跨午夜（start 大于 end）；start 等于 end（零长窗口）与解析失败一律算未命中——
 * 脏设置不该把通知全部吃掉。两端都是闭开 [start, end)。
 */
export function inWindowMinutes(minutes: number, start: string, end: string): boolean {
  const from = clockToMinutes(start);
  const to = clockToMinutes(end);
  if (Number.isNaN(from) || Number.isNaN(to)) return false;
  if (from === to) return false;
  if (from < to) return minutes >= from && minutes < to;
  return minutes >= from || minutes < to;
}

packages/dsh-notifier/src/shared/reason-.source:
/**
 * dsh-notifier —— 投递理由的 code 闭集（纯数据，无 import）。
 *
 * 为什么两端共用一份：`reasonLegacy` 此前在客户端是一份**靠注释维系的同值字面量**
 * （`const LEGACY_CODE = "reasonLegacy"`，注释自述「与服务端 REASON_LEGACY 同值」），而没有任何
 * 断言锁住两者相等——改一边就是一个读不出来的历史行。收口后客户端只消费这里这个值。
 *
 * 值函数（reason / normalizeReason / reasonFromCause / clampReasonDetail / sameReasonShape）不在这里：
 * 它们依赖 src/server/shared/text.ts 的截断实现，属宿主端，进不了零 import 的共享面。
 *
 * 生产侧闭集在本地，读侧仍是开放 string（磁盘上的旧行与跨版本数据不受本版编译期约束）。
 * 客户端字典必须覆盖 REASON_CODES 的每一项，跨端一致性由 test/client-unit/reason-text.test.ts 的
 * 直连断言守（客户端只把 REASON_LEGACY 当值用，REASON_CODES 只作类型来源）。
 */

/**
 * 升级前的散文理由。这一条是唯一「code 不含文案」的取值：原文整句进 `detail`，客户端逐字渲染。
 * 它只在割接产物上出现（见 upgrade 域的 reason 形态迁移），但会随历史记录长期留在磁盘上。
 */
export const REASON_LEGACY = "reasonLegacy";

/**
 * 本版会生产的 code 清单。命名即字典 key：`t(code, params)` 直接取文案，不另建一张
 * code → key 的映射表，少一处能漂的地方。
 */
export const REASON_CODES = [
  REASON_LEGACY,
  // 空动作（skipped）：`config` 是用户意图，`environment` 是环境能力。两者必须分得开——
  // 前者不该被当成故障去查，后者不该被当成「用户自己关的」而放过。
  "reasonSkipConfig",
  "reasonSkipEnvironment",
  // system 出口
  "reasonSystemPopupFailed",
  "reasonSystemSoundFailed",
  // win32 的 toast 脚本缺失是**打包缺陷**，与「宿主没能力」是两回事：合成一个 code 会把
  // 插件自己的问题说成用户的桌面环境问题，用户会去 Windows 上找一个不存在的 notify-send
  "reasonSystemToastScriptMissing",
  // 合成音的临时文件写不进去（/tmp 只读挂载、拿不到写权限）：这是一个**空动作**（没有可执行的
  // 播放动作），终态因此是 skipped 而不是 failed——宿主原文（EROFS/EACCES）进 detail。
  "reasonSystemToneUnwritable",
  // bark 出口
  "reasonBarkRequestFailed",
  "reasonBarkHttp",
  "reasonBarkRejected",
  "reasonBarkBodyUnreadable",
  // webhook 出口
  "reasonWebhookTemplateInvalid",
  "reasonWebhookRequestFailed",
  "reasonWebhookHttp",
  // 投递编排
  "reasonUnknownTarget",
  "reasonChannelThrew",
  // 节流命中：本次**没有投递**。把它记成上一次的结论，等于让归档替一次没发生的投递背书——
  // 通知记录是用户唯一能逐条看的投递面，那一行必须是这一次的事实。
  "reasonThrottled",
] as const;

export type ReasonCode = (typeof REASON_CODES)[number];

/** 理由参数：只收能被字典插值的标量——对象与数组进不来，文案层不必再判嵌套。 */
export type ReasonParams = Readonly<Record<string, string | number>>;

packages/dsh-notifier/src/shared/sounds..source:
/**
 * dsh-notifier —— 内置音色白名单（纯数据，无 import）。
 *
 * 为什么两端共用一份：白名单此前两端各写一份**逐字相同**的字面量（宿主端 config 的写入口径、
 * 客户端设置页的音色选项与「有没有声」的三态判定），新增音色时漏改一边的症状是「设置页给得出
 * 选项、宿主把它当脏值静默回落」或反过来「宿主放行、选项里选不到」。
 *
 * 字面量数组是**唯一的物理事实源**，`SoundId` 由它派生——值与类型各写一份，会在新增音色时
 * 漏改一边。顺序即设置页展示顺序。导出面上只有类型与只读数组两项（与收口前的声明形态一致），
 * 免得下游为「元组 vs 数组」多写一次断言或收窄。
 *
 * 「跟随系统默认」不占白名单位：它在设置面是 `true`，在音色表一侧对应的键是 tones.ts 的
 * FOLLOW_SYSTEM_TONE（"default"）——后者是伪音色 id，不在用户可选的音色白名单里。
 */
const SOUND_ID_LIST = ["ding", "bell", "chime", "pop"] as const;

/** 内置音色 id：全平台语义一致的白名单。 */
export type SoundId = (typeof SOUND_ID_LIST)[number];

/** 白名单的运行时形态；顺序即设置页的展示顺序。 */
export const SOUND_IDS: readonly SoundId[] = SOUND_ID_LIST;

/**
 * 运行时白名单校验：类型联合只在编译期存在，磁盘内容与设置提交传来的值不受它约束。
 * 两端此前各自内联这份成员判定（宿主端 config 一次、客户端两次），收口到这里。
 */
export function isSoundId(value: unknown): value is SoundId {
  return typeof value === "string" && (SOUND_ID_LIST as readonly string[]).includes(value);
}

packages/dsh-notifier/src/shared/tones.t.source:
/**
 * dsh-notifier —— 音色事实源（纯数据，无 import）。
 *
 * 为什么两端共用一份、且放在包内：音色此前有三份定义（客户端 Web Audio 的 playTone、
 * 服务端平台素材表、服务端合成表），三份各自演化已经实测出 `ding`/`bell` 性格写反这类
 * 「同一音色在试听与宿主上不是同一个音」的分叉，而人工同步三处正是它复发的原因。
 * 放进包内而不是任一端，是为了让浏览器端与宿主端都不必 import 对方的实现文件。
 *
 * `notes` 是播放语义的唯一定义：客户端试听/自播按下标逐音起振，宿主合成按同一段采样，
 * 故新增音色只改本文件一处。
 */

/** 一个音：相对音色起点的秒数 `at` 决定音符间静音，`type` 缺省为正弦。 */
export interface ToneNote {
  readonly freq: number;
  readonly at: number;
  readonly dur: number;
  readonly type?: "sine" | "triangle";
}

/**
 * 一个音色的全部事实。三个平台素材字段都可选：没有素材语义的音色（例如纯合成音）
 * 在有主题文件的宿主上应当静默，而不是随便挑一个别的文件顶替。
 */
export interface ToneSpec {
  readonly notes: readonly ToneNote[];
  /** freedesktop 主题文件候选（首存在者胜）：有主题的宿主走素材，听感更好。 */
  readonly linuxFile?: readonly string[];
  /** NSSound 名（osascript `sound name`）。 */
  readonly darwinSound?: string;
  /** C:\Windows\Media 白名单候选；缺失静默。 */
  readonly win32File?: readonly string[];
}

/**
 * 「跟随系统默认音」的伪音色 id。
 *
 * 它是设置面 `sound: true`、宿主自播与平台素材表共同指向的同一个键：此前这个字符串散在
 * 四处各写一遍，任一处漂移都会让「跟随系统」在某个平台上指向不存在的音色而静默。
 */
export const FOLLOW_SYSTEM_TONE = "default";

/**
 * 音色表。`notes` 与客户端合并前逐项一致（ding=双短高音、bell=单中高音、chime=三音上行、
 * pop=三角波短促低音、default=双音下行）；平台素材沿用合并前的服务端表。
 */
export const TONES: Readonly<Record<string, ToneSpec>> = {
  [FOLLOW_SYSTEM_TONE]: {
    notes: [
      { freq: 880, at: 0, dur: 0.16 },
      { freq: 660, at: 0.16, dur: 0.22 },
    ],
    linuxFile: ["message-new-instant.oga"],
    darwinSound: "Glass",
    win32File: ["Windows Notify System Generic.wav", "Windows Ding.wav"],
  },
  ding: {
    notes: [
      { freq: 1318, at: 0, dur: 0.14 },
      { freq: 1760, at: 0.16, dur: 0.22 },
    ],
    linuxFile: ["message-new-instant.oga"],
    darwinSound: "Glass",
    win32File: ["Windows Ding.wav"],
  },
  bell: {
    notes: [{ freq: 880, at: 0, dur: 0.5 }],
    linuxFile: ["bell.oga"],
    darwinSound: "Tink",
    win32File: ["Windows Chimes.wav"],
  },
  chime: {
    notes: [
      { freq: 660, at: 0, dur: 0.3 },
      { freq: 880, at: 0.15, dur: 0.3 },
      { freq: 1320, at: 0.3, dur: 0.5 },
    ],
    linuxFile: ["complete.oga", "dialog-information.oga"],
    darwinSound: "Sosumi",
    win32File: ["Windows Chord.wav", "Windows Notify System Generic.wav"],
  },
  pop: {
    notes: [{ freq: 392, at: 0, dur: 0.12, type: "triangle" }],
    linuxFile: ["message.oga", "dialog-information.oga"],
    darwinSound: "Pop",
    win32File: ["Windows Balloon.wav", "Windows Notify System Generic.wav"],
  },
};

packages/dsh-notifier/src/shared/webhook.source:
/**
 * dsh-notifier —— webhook 预设的共享面：默认模板、`{{priority}}` 映射、认证方式白名单，
 * 以及「配置层预设 → 投递层预设」的改名（纯数据 + 两个纯映射函数，只做同目录类型 import）。
 *
 * 为什么两端共用一份：客户端「选预设 → 填充模板」与宿主端「按预设渲染 body」此前各写一份
 * **逐字相同**的模板（收口时已机器比对：三对字面量逐字节相等）。漂移的症状是「设置页上看到的
 * 模板与实际发出去的 body 不是同一份」——用户既改不回默认值，也解释不了对端收到的字段。
 *
 * 两层词汇必须分开：配置层 / 设置页叫 `custom`，投递层叫 `raw`（同一个东西），改名只此一处
 * （`deliveryPresetOf`）。认证**方式**白名单是两端共有的；「预设 → 认证方式」的默认值
 * （ntfy / gotify → bearer、custom → header）只在客户端有对应物——宿主端没有「套用预设」这个
 * 动作，故那半张表留在客户端。
 */
import type { NotifySeverity } from "./kinds.ts";

/** 配置层 / 设置页的预设白名单（顺序即下拉顺序）。 */
export const WEBHOOK_PRESETS = ["ntfy", "gotify", "custom"] as const;

/** 配置层的预设。 */
export type WebhookPreset = (typeof WEBHOOK_PRESETS)[number];

/** 投递层的预设白名单（配置层的 `custom` 在投递层叫 `raw`）。 */
export const WEBHOOK_DELIVERY_PRESETS = ["ntfy", "gotify", "raw"] as const;

/** 投递层的预设。 */
export type WebhookDeliveryPreset = (typeof WEBHOOK_DELIVERY_PRESETS)[number];

/**
 * 预设默认模板（逐字保留自收口前的两份副本）。模板是 JSON 文本：`{{ts}}` 之外的空模板由宿主端
 * 渲染器回落，客户端的「恢复默认模板」直接取这里的字面量。
 */
export const WEBHOOK_DEFAULT_TEMPLATES: Readonly<Record<WebhookDeliveryPreset, string>> = {
  ntfy: '{\n  "topic": "<topic>",\n  "title": "{{title}}",\n  "message": "{{message}}",\n  "tags": ["{{kind}}"],\n  "priority": "{{priority}}"\n}',
  gotify:
    '{\n  "title": "{{title}}",\n  "message": "{{message}}",\n  "priority": "{{priority}}"\n}',
  raw: '{\n  "event": "{{kind}}",\n  "title": "{{title}}",\n  "body": "{{message}}",\n  "severity": "{{severity}}",\n  "ts": {{ts}}\n}',
};

/** `{{priority}}` 映射表（`raw` = severity 原文）；查不到即 severity 非法，视同未提供。 */
export const WEBHOOK_PRIORITY: Readonly<
  Record<WebhookDeliveryPreset, Readonly<Record<NotifySeverity, string>>>
> = {
  ntfy: { failure: "urgent", warning: "high", success: "low", info: "default" },
  gotify: { failure: "9", warning: "7", success: "3", info: "3" },
  raw: { failure: "failure", warning: "warning", success: "success", info: "info" },
};

/** 认证方式白名单（顺序即下拉顺序）。凭据一律走请求头，故没有「URL 内联凭据」这一档。 */
export const WEBHOOK_AUTHS = ["none", "bearer", "basic", "header"] as const;

/** 认证方式。 */
export type WebhookAuth = (typeof WEBHOOK_AUTHS)[number];

/** 配置层预设 → 投递层预设。两层词汇的唯一改名点。 */
export function deliveryPresetOf(preset: WebhookPreset): WebhookDeliveryPreset {
  return preset === "custom" ? "raw" : preset;
}

/** 配置层预设的默认模板（改名与查表都只此一处）。 */
export function webhookTemplateOf(preset: WebhookPreset): string {
  return WEBHOOK_DEFAULT_TEMPLATES[deliveryPresetOf(preset)];
}

packages/dsh-notifier/test/unit/channels.source:
/**
 * dsh-notifier channels 域 system 出口 —— 命令构造、平台探测、自播判定与执行编排。
 *
 * 判据为什么是这些：命令一律 `[bin, ...args]` 且用户文本只经 base64 载荷进 PowerShell——这条
 * 一旦退化成拼命令串，通知标题里的一个引号就是本机命令执行；自播判定错了则要么响两声、要么
 * 「只响不弹」静默变成一次无声的失败；探测与执行错了则平台分支、探测失败、杀进程超时、退出码
 * 异常这些出口在真机上全都不可复现。
 *
 * 平台事实与子进程经 `impl/system/deps.ts` 的手写假端口驱动：真机上三条平台分支只有一条可达，
 * 而在本机真的起 `notify-send` / `afplay` 既弹窗又发声，且结论随环境而变。
 */
import {
  existsSync,
  mkdtempSync,
  readdirSync,
  readFileSync,
  rmSync,
  statSync,
  symlinkSync,
  writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { basename, dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import type {
  DeliverResult,
  NotifyMessage,
} from "../../../src/server/channels/impl/deliver/type.ts";
import { releaseSoundTemps } from "../../../src/server/channels/interface.ts";
import {
  RealToneTemps,
  installSystemDeps,
  releaseSystemDeps,
  systemDeps,
} from "../../../src/server/channels/impl/system/deps.ts";
import type {
  ChildHandle,
  ProcessExit,
  SpawnOptions,
  SystemDeps,
} from "../../../src/server/channels/impl/system/deps.ts";
import type {
  CommandFacts,
  CommandOutcome,
  NotificationNameProbe,
  OsReleaseProbe,
  ToneStage,
} from "../../../src/server/channels/impl/system/type.ts";
import {
  LINUX_PLAYERS,
  playerSpec,
  playFailure,
  playFailureSummary,
} from "../../../src/server/channels/impl/system/players.ts";
import type { PlayerSpec } from "../../../src/server/channels/impl/system/players.ts";
import {
  buildSoundCommands,
  buildSystemCommand,
  probePlatform,
  sendSystem,
  shouldSelfPlay,
} from "../../../src/server/channels/impl/system/index.ts";
import { synthToneWav } from "../../../src/server/channels/impl/system/synth.ts";
import { toneFileCandidates } from "../../../src/server/channels/impl/system/tones.ts";
import { SOUND_IDS, TONES } from "../../../src/shared/interface.ts";
import type {
  PlatformProbe,
  SystemCommandOptions,
  SystemTarget,
} from "../../../src/server/channels/impl/system/type.ts";
import { makeLogger, pollUntil } from "../../helpers.ts";

/** 表序 = 链序：链序类判据的期望值一律从表导出，播放器名与顺序都不许在用例里再抄一份。 */
const CHAIN_BINS = LINUX_PLAYERS.map((player) => player.bin);
/** 表内第一条探测参数（`bin args` 形态）：探测类判据拿它拼期望，不重抄参数。 */
const firstProbeOf = (player: PlayerSpec): string =>
  `${player.bin} ${player.probeArgs[0]!.join(" ")}`;
/** 表内全部探测参数（表序 × 每行的参数序）：一个候选都没命中时，它的每条参数都会被试到。 */
const ALL_PROBES = LINUX_PLAYERS.flatMap((player) =>
  player.probeArgs.map((args) => `${player.bin} ${args.join(" ")}`),
);
/** 假端口落的临时文件所在目录（假实现不碰文件系统，路径只作身份）。 */
const FAKE_TONE_DIR = "/tmp/dsh-notifier-fake";
/** 实测样本：成功路径上也会出现的 libasound 噪声（40 次里 3 次）。 */
const ALSA_UNDERRUN = "ALSA lib pcm.c:8568:(snd_pcm_recover) underrun occurred\n";
/** 让探测/投递的 await 链走完（断言「探测已经发出几条」时比 pollUntil 更直接）。 */
const flushTasks = (): Promise<void> => new Promise((resolve) => setTimeout(resolve, 0));

afterEach(() => {
  // 端口与探测缓存都是模块级单例：不复位就把平台事实漏给下一个用例（单跑绿、连跑红）。
  releaseSystemDeps();
  vi.useRealTimers();
  // 真端口建的临时音频目录：用例漏了释放就在这里兜底——残留会让下一个用例（与 smoke）看见别人
  // 的目录，而「临时目录有残留」正是本增量要判死的一件事。
  releaseSoundTemps();
});

function probeOf(over: Partial<PlatformProbe> = {}): PlatformProbe {
  return {
    platform: "linux",
    toastScriptAvailable: true,
    notifySendAvailable: true,
    players: ["pw-play"],
    ...over,
  };
}

function optionsOf(over: Partial<SystemCommandOptions> = {}): SystemCommandOptions {
  return { sound: true, selfPlay: false, toastScript: "/tmp/notifier/toast.ps1", ...over };
}

/** 取 PowerShell 命令里那段 base64 载荷：win32 的用户文本只在这里，不进 argv。 */
function payloadOf(command: readonly string[]): Record<string, unknown> {
  const index = command.indexOf("-Payload");
  if (index < 0) throw new Error("命令里没有 -Payload");
  return JSON.parse(Buffer.from(command[index + 1]!, "base64").toString("utf8")) as Record<
    string,
    unknown
  >;
}

// ---------------------------------------------------------------- 假进程事实端口

/** 假子进程：三个出口都由用例显式驱动，不依赖真实进程的调度。 */
class FakeChild implements ChildHandle {
  /** 兜底杀进程的次数（超时用例断言它）。 */
  killCount = 0;

  private readonly exits: Array<(exit: ProcessExit) => void> = [];
  private readonly errors: Array<(cause: Error) => void> = [];
  private readonly stderrs: Array<(chunk: Buffer) => void> = [];

  /** 结局到达的回执：临时文件的删除必须晚于它（D3 判据靠这条时序）。 */
  constructor(private readonly onExitEmitted: (() => void) | undefined = undefined) {}

  onStderr(handler: (chunk: Buffer) => void): void {
    this.stderrs.push(handler);
  }

  onExit(handler: (exit: ProcessExit) => void): void {
    this.exits.push(handler);
  }

  onError(handler: (cause: Error) => void): void {
    this.errors.push(handler);
  }

  kill(): void {
    this.killCount += 1;
  }

  emitStderr(text: string): void {
    for (const handler of this.stderrs) handler(Buffer.from(text, "utf8"));
  }

  emitExit(exit: ProcessExit): void {
    this.onExitEmitted?.();
    for (const handler of this.exits) handler(exit);
  }

  emitError(cause: Error): void {
    for (const handler of this.errors) handler(cause);
  }
}

/** 假端口的现场：用例只写关心的那几项，其余走 `fakeDeps()` 的缺省。 */
interface FakeConfig {
  platform: string;
  /** 探测得到回应的命令（该 bin 的任何参数都以退出码 0 结束）。 */
  available: readonly string[];
  /** `existsSync` 为真的路径。 */
  present: readonly string[];
  /** 逐条探测的可用性（`"ffplay -version"` 形态）：各播放器的版本参数不统一，探测判据要它。 */
  availableProbes?: readonly string[];
  /** 这些 bin 的**首条**探测被扣住（并发探测的判据要它：先发出全部探测，再放行）。 */
  holdProbes?: readonly string[];
  /** 通知守护进程名的探测结论。 */
  nameProbe?: NotificationNameProbe;
  /** `/etc/os-release` 的读取结论。 */
  osRelease?: OsReleaseProbe;
}

/** 起进程的记录：逐字 argv 与选项都要它。 */
interface SpawnRecord {
  readonly command: readonly string[];
  readonly options: SpawnOptions;
}

/** 探测的记录：命令、参数与超时都要它。 */
interface ProbeRecord {
  readonly bin: string;
  readonly args: readonly string[];
  readonly timeout: number;
}

/** 假进程事实端口：记下每一次调用，子进程交回可由用例驱动的假句柄。 */
class FakeDeps implements SystemDeps {
  readonly platform: string;
  readonly spawned: SpawnRecord[] = [];
  readonly children: FakeChild[] = [];
  readonly probed: ProbeRecord[] = [];
  readonly checked: string[] = [];
  /** 非空 = `spawn` 同步抛出这个消息（真机上对应 argv 非法、权限不足）。 */
  spawnFailure = "";
  /** 假 = 抛出的不是 `Error`（跨边界值仍要留下可读的原因）。 */
  spawnFailureIsError = true;
  /** 假 = 子进程的结局由用例驱动（超时、stderr 尾部、双出口竞争这些用例要它）。 */
  autoExit = true;
  /** 自动退出用的退出码。 */
  exitCode = 0;

  /** 用例关心的时序（探测/落盘/起进程/结局/删除）：只在这个数组里判「谁先谁后」。 */
  readonly events: string[] = [];
  /** 当前还在盘上的临时音频文件（路径 → 字节）：unstage 会把它删掉，故它判「活着没有」。 */
  readonly stagedFiles = new Map<string, Buffer>();
  /** 落过盘的东西（含已被 unstage 的）：素材字节的判据看它（投递结束时 live 表已经空了）。 */
  readonly stagedHistory = new Map<string, Buffer>();
  /** 被扣住的探测回调；`releaseProbes()` 放行（并发探测用例）。 */
  readonly pendingProbes: Array<() => void> = [];
  /** 已 unstage 的路径。 */
  readonly unstaged: string[] = [];
  /** 非空 = `stageToneAudio` 回这个原因（`/tmp` 只读挂载的等价物）。 */
  stageFailure = "";
  /** 临时目录是否被释放面收走：**按次投递**就删目录的实现在这里会红。 */
  toneDirReleased = false;

  private readonly available: readonly string[];
  private readonly present: readonly string[];
  private readonly availableProbes: readonly string[];
  private readonly holdProbes: readonly string[];
  private readonly nameProbe: NotificationNameProbe;
  private readonly osRelease: OsReleaseProbe;
  private stagedSeq = 0;

  constructor(config: FakeConfig) {
    this.platform = config.platform;
    this.available = config.available;
    this.present = config.present;
    this.availableProbes = config.availableProbes ?? [];
    this.holdProbes = config.holdProbes ?? [];
    this.nameProbe = config.nameProbe ?? { kind: "absent" };
    this.osRelease = config.osRelease ?? { ok: false };
  }

  spawn(command: readonly string[], options: SpawnOptions): ChildHandle {
    this.spawned.push({ command, options });
    this.events.push(`spawn:${command[0] ?? "unknown"}`);
    if (this.spawnFailure !== "") {
      throw this.spawnFailureIsError ? new Error(this.spawnFailure) : this.spawnFailure;
    }
    const child = new FakeChild(() => this.events.push(`exit:${command[0] ?? "unknown"}`));
    this.children.push(child);
    // 出口监听在同一个 tick 里挂上，故微任务里的自动退出不会漏事件
    if (this.autoExit) queueMicrotask(() => child.emitExit({ exited: true, code: this.exitCode }));
    return child;
  }

  execFile(
    bin: string,
    args: readonly string[],
    options: { readonly timeout: number },
    done: (failed: boolean) => void,
  ): void {
    this.probed.push({ bin, args, timeout: options.timeout });
    const failed =
      !this.available.includes(bin) && !this.availableProbes.includes(`${bin} ${args.join(" ")}`);
    // 只扣首条：表里第二条参数（ffplay 的 `-h`）是「首条失败才试」的那一条，扣住它会让放行后
    // 又立刻挂上一条新的，探测永远收不了尾
    const firstForBin = this.probed.filter((record) => record.bin === bin).length === 1;
    if (firstForBin && this.holdProbes.includes(bin)) {
      this.pendingProbes.push(() => done(failed));
      return;
    }
    done(failed);
  }

  /** 放行被扣住的探测回调（探测并发用例）。 */
  releaseProbes(): void {
    for (const call of this.pendingProbes.splice(0)) call();
  }

  stageToneAudio(bytes: Buffer): ToneStage {
    if (this.stageFailure !== "") return { ok: false, cause: this.stageFailure };
    this.stagedSeq += 1;
    const path = join(FAKE_TONE_DIR, `tone-${this.stagedSeq}.wav`);
    this.stagedFiles.set(path, bytes);
    this.stagedHistory.set(path, bytes);
    this.events.push(`stage:${path}`);
    return { ok: true, path };
  }

  unstageToneAudio(path: string): void {
    this.unstaged.push(path);
    this.events.push(`unstage:${path}`);
    this.stagedFiles.delete(path);
  }

  releaseToneTemps(): void {
    this.toneDirReleased = true;
    this.events.push("release");
    this.stagedFiles.clear();
  }

  existsSync(path: string): boolean {
    this.checked.push(path);
    return this.present.includes(path);
  }

  probeNotificationName(): Promise<NotificationNameProbe> {
    return Promise.resolve(this.nameProbe);
  }

  readOsRelease(): OsReleaseProbe {
    return this.osRelease;
  }
}

/** 造一份假端口；缺省是「linux 上什么都没有」。 */
function fakeDeps(over: Partial<FakeConfig> = {}): FakeDeps {
  return new FakeDeps({ platform: "linux", available: [], present: [], ...over });
}

/** 通知脚本路径（内容无关，只作探测与 argv 的身份）。 */
const TOAST_SCRIPT = "/tmp/notifier/toast.ps1";
/** Linux ding 的自播文件（freedesktop 基线包内的绝对路径）。 */
const LINUX_DING_FILE = "/usr/share/sounds/freedesktop/stereo/message-new-instant.oga";
/** 待投递消息：`ts` 写死不取 `Date.now()`，免得断言跟着运行时刻漂。 */
const MESSAGE: NotifyMessage = { title: "标题", body: "正文", kind: "done", ts: 1_700_000_000_000 };

/** 一次系统投递的现场：目标可覆盖，warn 文案收集在一处供断言。 */
class SystemDelivery {
  private readonly logger = makeLogger();
  private readonly target: SystemTarget;

  constructor(over: Partial<SystemTarget> = {}) {
    this.target = {
      type: "system",
      popup: true,
      sound: false,
      toastScript: TOAST_SCRIPT,
      logger: this.logger,
      ...over,
    };
  }

  get warns(): readonly string[] {
    return this.logger.warns;
  }

  send(message: NotifyMessage = MESSAGE): Promise<DeliverResult> {
    return sendSystem(this.target, message);
  }
}

/** 等真实子进程的第一次退出事实。 */
function exitOf(handle: ChildHandle): Promise<ProcessExit> {
  return new Promise((resolve) => {
    handle.onExit(resolve);
  });
}

/** 等真实子进程的第一段 stderr 文本。 */
function stderrOf(handle: ChildHandle): Promise<string> {
  return new Promise((resolve) => {
    handle.onStderr((chunk) => {
      resolve(chunk.toString("utf8"));
    });
  });
}

/** 等真实子进程的启动失败事实。 */
function errorOf(handle: ChildHandle): Promise<Error> {
  return new Promise((resolve) => {
    handle.onError(resolve);
  });
}

/** 真实端口探一次命令；`failed` 即命令不可用。 */
function probeFailed(bin: string, args: readonly string[]): Promise<boolean> {
  return new Promise((resolve) => {
    systemDeps().execFile(bin, args, { timeout: 3000 }, resolve);
  });
}

describe("buildSystemCommand", () => {
  // 用户文本进 argv 就是命令注入面，base64 载荷是这条命令唯一的安全通道。
  it("win32：用户文本只走 base64 载荷，argv 里没有它（命令 tokenizer 的歧义面被彻底绕开）", () => {
    const command = buildSystemCommand(
      probeOf({ platform: "win32" }),
      "标题",
      "正文",
      optionsOf({ sound: false }),
    );
    expect(command.slice(0, 7)).toEqual([
      "powershell",
      "-NoProfile",
      "-NonInteractive",
      "-ExecutionPolicy",
      "Bypass",
      "-File",
      "/tmp/notifier/toast.ps1",
    ]);
    expect(command[7]).toBe("-Payload");
    expect(command.join(" ")).not.toContain("标题");
    expect(payloadOf(command)).toEqual({ title: "标题", message: "正文", silent: true });

    // silent 的判据：不发声，或出口要自播（自播时弹窗不静音就会响两声）。
    const loud = buildSystemCommand(probeOf({ platform: "win32" }), "标", "正", optionsOf());
    expect(payloadOf(loud).silent).toBe(false);
    const selfPlayed = buildSystemCommand(
      probeOf({ platform: "win32" }),
      "标",
      "正",
      optionsOf({ selfPlay: true }),
    );
    expect(payloadOf(selfPlayed).silent).toBe(true);
  });

  // 脚本缺失是打包缺陷，命令都没构造出来时调用方需要一条可查的痕迹。
  it("win32 缺 toast 脚本 → 空命令（打包缺陷不该被当成一次普通的发送失败闷掉）", () => {
    expect(
      buildSystemCommand(
        probeOf({ platform: "win32", toastScriptAvailable: false }),
        "标题",
        "正文",
        optionsOf(),
      ),
    ).toEqual([]);
  });

  // 裸引号或裸换行会让 osascript 脚本语法错误、通知直接不发；音色写错则静默无声。
  it("darwin：转义引号与反斜杠、换行换空格；音色查表并回落 Glass，静音时不写 sound name", () => {
    const probe = probeOf({ platform: "darwin", notifySendAvailable: false, players: ["afplay"] });
    const command = buildSystemCommand(
      probe,
      '他说 "你好"\\路径',
      "第一行\n第二行",
      optionsOf({ sound: "bell" }),
    );
    expect(command[0]).toBe("osascript");
    expect(command[1]).toBe("-e");
    expect(command[2]).toBe(
      'display notification "第一行 第二行" with title "他说 \\"你好\\"\\\\路径" sound name "Tink"',
    );
    expect(command[2]).not.toContain("\n");

    const fallback = buildSystemCommand(probe, "标", "正", optionsOf({ sound: "不存在的音色" }));
    expect(fallback[2]).toContain('sound name "Glass"');
    const silent = buildSystemCommand(probe, "标", "正", optionsOf({ sound: false }));
    expect(silent[2]).not.toContain("sound name");
    const selfPlayed = buildSystemCommand(probe, "标", "正", optionsOf({ selfPlay: true }));
    expect(selfPlayed[2]).not.toContain("sound name");
  });

  // 各 DE 对 sound hint 支持参差，探测不到却硬发会把失败推给运行时。
  it("linux：恒带 suppress-sound hint（发声一律由自播承担）；探测不到 notify-send 就不给命令", () => {
    expect(buildSystemCommand(probeOf(), "标题", "正文", optionsOf())).toEqual([
      "notify-send",
      "-h",
      "boolean:suppress-sound:true",
      "标题",
      "正文",
    ]);
    expect(
      buildSystemCommand(probeOf({ notifySendAvailable: false }), "标题", "正文", optionsOf()),
    ).toEqual([]);
  });
});

