/**
 * dsh-notifier src/shared/quiet —— 免打扰共享面的单源判据。
 *
 * 收口起因：上限（服务端 5 / 客户端 5）与区间口径（judge parseClock+inWindow、
 * input CLOCK_PATTERN+asQuietWindow、客户端 clockToMinutesLocal+windowHitLocal）
 * 各写一份，口径一致全靠人工同步。收口后三端消费同一个绑定，「同值同口径」由构造保证；
 * 本文件再把值、口径与「各端不再有第二份字面量/第二份实现」钉成可判红的判据。
 */
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { afterEach, describe, expect, it, vi } from "vitest";

import {
  QUIET_WINDOWS_LIMIT,
  inWindowMinutes,
  isClockText,
} from "../../../src/shared/interface.ts";
import { QUIET_WINDOWS_LIMIT as MODEL_LIMIT } from "../../../src/server/config/impl/model/type.ts";
import { DEFAULT_CONFIG } from "../../../src/server/config/impl/model/index.ts";
import { normalizeConfig, validateSettings } from "../../../src/server/config/impl/input/index.ts";
import { inWindow, judgeRequest } from "../../../src/server/pipeline/impl/judge/index.ts";

const pkgDir = fileURLToPath(new URL("../../../", import.meta.url));

afterEach(() => {
  vi.useRealTimers();
});

describe("上限单源：两端读同一个数", () => {
  it("共享值钉住 5，模型侧只是转出（改一边即红）", () => {
    expect(QUIET_WINDOWS_LIMIT).toBe(5);
    expect(MODEL_LIMIT).toBe(QUIET_WINDOWS_LIMIT);
  });

  it("客户端不再抄一份 VIEW 常量", () => {
    const src = readFileSync(join(pkgDir, "src/client/settings/panes/events.tsx"), "utf8");
    expect(src).not.toMatch(/QUIET_WINDOWS_LIMIT_VIEW/u);
    expect(src).toContain("QUIET_WINDOWS_LIMIT");
    expect(src).toContain('from "../../../shared/interface.ts"');
  });
});

describe("命中口径三端同表：共享 / 裁决同行", () => {
  it.each<[number, string, string, boolean]>([
    [23 * 60, "22:00", "08:00", true],
    [8 * 60, "22:00", "08:00", false],
    [22 * 60, "22:00", "08:00", true],
    [13 * 60 + 30, "13:00", "14:00", true],
    [14 * 60, "13:00", "14:00", false],
    [12 * 60, "12:00", "12:00", false],
    [12 * 60, "25:00", "08:00", false],
    [12 * 60, "22:00", "nope", false],
  ])("inWindowMinutes(%i, %s, %s) = %s，且裁决侧同行", (minutes, start, end, hit) => {
    expect(inWindowMinutes(minutes, start, end)).toBe(hit);
    expect(inWindow(minutes, start, end)).toBe(hit);
  });

  it("时钟形状两端同源：合法放行、非法拒绝", () => {
    for (const clock of ["00:00", "22:00", "23:59"]) expect(isClockText(clock)).toBe(true);
    for (const clock of ["24:00", "22:60", "9:30", "abc", "", "22:00:00"]) {
      expect(isClockText(clock)).toBe(false);
    }
  });

  it("写面与读面同口径：合法窗口放行，非法/零长拒绝或丢项", () => {
    expect(
      validateSettings({
        quietHours: { enabled: true, windows: [{ start: "22:00", end: "08:00" }] },
      }),
    ).toEqual({ ok: true });
    for (const windows of [
      [{ start: "25:00", end: "08:00" }],
      [{ start: "22:00", end: "22:00" }],
    ]) {
      const verdict = validateSettings({ quietHours: { enabled: true, windows } });
      if (verdict.ok) throw new Error("期望判非法，实际放行：" + JSON.stringify(windows));
      expect(verdict.error.key).toBe("quietHours");
    }
    // 读面：非法单项只废该项，合法窗口保留；显式 [] 保持 []（空数组 = 未命中）。
    const kept = normalizeConfig({
      quietHours: {
        enabled: true,
        windows: [
          { start: "nope", end: "08:00" },
          { start: "22:00", end: "08:00" },
        ],
      },
    });
    expect(kept.quietHours.windows).toEqual([{ start: "22:00", end: "08:00" }]);
    expect(
      normalizeConfig({ quietHours: { enabled: true, windows: [] } }).quietHours.windows,
    ).toEqual([]);
  });

  it("裁决脏项不抛：非对象单项按未命中跳过（活链上不抛，见 judge 文件头）", () => {
    vi.setSystemTime(new Date(2026, 0, 15, 23, 0, 0));
    const dirty = {
      ...DEFAULT_CONFIG,
      quietHours: {
        enabled: true,
        windows: ["x", null, 42, { start: "22:00", end: "08:00" }] as unknown as {
          start: string;
          end: string;
        }[],
      },
    };
    expect(() => judgeRequest(dirty, { kind: "done", title: "t", body: "b" }, true)).not.toThrow();
    expect(judgeRequest(dirty, { kind: "done", title: "t", body: "b" }, true)).toEqual({
      ok: false,
      reason: "quiet",
    });
    const allDirty = {
      ...DEFAULT_CONFIG,
      quietHours: {
        enabled: true,
        windows: ["x", null] as unknown as { start: string; end: string }[],
      },
    };
    expect(judgeRequest(allDirty, { kind: "done", title: "t", body: "b" }, true)).toEqual({
      ok: true,
    });
  });

  it("客户端回显走共享命中，不再自备区间实现", () => {
    const src = readFileSync(join(pkgDir, "src/client/settings/panes/events.tsx"), "utf8");
    expect(src).not.toMatch(/function windowHitLocal/u);
    expect(src).not.toMatch(/function clockToMinutesLocal/u);
    expect(src).toContain("inWindowMinutes");
  });
});

packages/dsh-notifier/test/unit/shared/k.source:
/**
 * dsh-notifier src/shared —— 通知类型表（两端共享面）的直连判据。
 *
 * 值逐项钉住而不是「表里有几项」：宿主端的裁决开关与客户端的事件卡/色点读同一张表，
 * 漏配一项的症状是「界面给得出、宿主不认」，只看长度或只看键集都抓不到。
 */
import { describe, expect, it } from "vitest";

import { BOOLEAN_KEYS } from "../../../src/server/config/impl/input/index.ts";
import { DEFAULT_CONFIG } from "../../../src/server/config/impl/model/index.ts";
import {
  BUILTIN_KINDS,
  KIND_SEVERITY,
  KIND_SWITCHES,
  NOTIFY_SEVERITIES,
  isBuiltinKind,
  isNotifySeverity,
} from "../../../src/shared/interface.ts";

describe("BUILTIN_KINDS / isBuiltinKind", () => {
  it("取值与顺序逐项钉住（顺序即设置页展示顺序）", () => {
    expect([...BUILTIN_KINDS]).toEqual([
      "ask",
      "question",
      "done",
      "subagent-done",
      "error",
      "turn-end",
      "test",
    ]);
  });

  it("isBuiltinKind 只认内置名；外部 命名空间:id 与近似拼写一律判否", () => {
    for (const kind of BUILTIN_KINDS) expect(isBuiltinKind(kind), kind).toBe(true);
    const rejected = ["demo:report", "ask:", ":ask", "Test", "turn_end", "ask ", "", "test2"];
    for (const kind of rejected) expect(isBuiltinKind(kind), kind).toBe(false);
  });

  it("内置名一律不含冒号（与外部命名空间天然不相交）", () => {
    expect(BUILTIN_KINDS.filter((kind) => kind.includes(":"))).toEqual([]);
  });
});

describe("KIND_SEVERITY / NOTIFY_SEVERITIES / isNotifySeverity", () => {
  it("键集与 BUILTIN_KINDS 逐项一致（新增 kind 漏配强度在这里红）", () => {
    expect(Object.keys(KIND_SEVERITY).sort()).toEqual([...BUILTIN_KINDS].sort());
  });

  it("取值逐项钉住（客户端色点与服务端定稿读同一张表）", () => {
    expect(KIND_SEVERITY).toEqual({
      ask: "warning",
      question: "info",
      done: "success",
      "subagent-done": "info",
      error: "failure",
      "turn-end": "info",
      test: "info",
    });
  });

  it("NOTIFY_SEVERITIES 取值与顺序逐项钉住，且覆盖 KIND_SEVERITY 的全部取值", () => {
    expect([...NOTIFY_SEVERITIES]).toEqual(["info", "success", "warning", "failure"]);
    for (const kind of BUILTIN_KINDS) {
      expect(NOTIFY_SEVERITIES, kind).toContain(KIND_SEVERITY[kind]);
    }
  });

  it("isNotifySeverity 边界：大小写与未知档一律判非法（跨边界值不得被放行）", () => {
    for (const severity of NOTIFY_SEVERITIES) {
      expect(isNotifySeverity(severity), severity).toBe(true);
    }
    const rejected = ["Info", "critical", "warn", "", " info"];
    for (const value of rejected) {
      expect(isNotifySeverity(value), value).toBe(false);
    }
  });
});

describe("KIND_SWITCHES：kind → 事件开关键", () => {
  it("键集 = BUILTIN_KINDS 去掉 test（test 不对应任何宿主事件，也就没有开关）", () => {
    expect(Object.keys(KIND_SWITCHES).sort()).toEqual(
      BUILTIN_KINDS.filter((kind) => kind !== "test").sort(),
    );
  });

  it("值逐项钉住，且都是设置模型里真实存在的布尔键（同 BOOLEAN_KEYS 的键集）", () => {
    expect(KIND_SWITCHES).toEqual({
      ask: "notifyAsk",
      question: "notifyQuestion",
      done: "notifyTaskDone",
      "subagent-done": "notifySubagentDone",
      error: "notifyTaskError",
      "turn-end": "notifyTurnEnd",
    });
    expect([...Object.values(KIND_SWITCHES)].sort()).toEqual([...BOOLEAN_KEYS].sort());
    for (const key of Object.values(KIND_SWITCHES)) {
      expect(typeof DEFAULT_CONFIG[key], key).toBe("boolean");
    }
  });

  // 客户端那张逆向表（开关键 → kind）由本表反转得到，故这里把反转结果也钉住：
  // 收口前它是客户端手里的一份副本，两份漂移的症状是「事件卡色点与开关对不上号」。
  it("反转即客户端的开关键 → kind 表（收口前那份副本逐项一致）", () => {
    const inverted = Object.fromEntries(
      Object.entries(KIND_SWITCHES).map(([kind, key]) => [key, kind]),
    );
    expect(inverted).toEqual({
      notifyAsk: "ask",
      notifyQuestion: "question",
      notifyTaskDone: "done",
      notifySubagentDone: "subagent-done",
      notifyTaskError: "error",
      notifyTurnEnd: "turn-end",
    });
  });
});

packages/dsh-notifier/test/unit/pipeline.source:
/**
 * dsh-notifier pipeline 域 finalize 块 —— 请求加工成待投递消息。
 *
 * 判据为什么是这些：
 *  - 强度缺省按 kind 补齐，外部 kind 则**缺席**而不是补一个中间档：出口的缺省路径已经定义了
 *    「未提供」的语义，这里再补一套就是第二个默认值来源；
 *  - 标题按码点截断、正文不截断：正文长度权威在各出口自己那里（bark 4096 / 页面 2048 /
 *    系统通知 256），在这里截会把系统通知的上限强加给所有出口。
 */
import { describe, expect, it } from "vitest";

import { finalizeRequest } from "../../../src/server/pipeline/impl/finalize/index.ts";
import { BUILTIN_KINDS } from "../../../src/server/pipeline/impl/service/kinds.ts";
import type { BuiltinKind } from "../../../src/server/pipeline/impl/service/kinds.ts";
import type { NotifyRequest } from "../../../src/server/pipeline/impl/service/type.ts";
import type { NotifySeverity } from "../../../src/server/pipeline/deps.ts";
import { wire } from "../../helpers.ts";

/**
 * 内置 kind → 缺省强度。独立写一遍而不是从源码导：值表漂移必须在这里红，抄源码就恒真了。
 * 表的完整性由「种类逐个对齐 `BUILTIN_KINDS`」那一条兜住。
 */
const KIND_SEVERITY_EXPECTED: ReadonlyArray<readonly [BuiltinKind, NotifySeverity]> = [
  ["ask", "warning"],
  ["question", "info"],
  ["done", "success"],
  ["subagent-done", "info"],
  ["error", "failure"],
  ["turn-end", "info"],
  ["test", "info"],
];

function requestOf(over: Partial<NotifyRequest> = {}): NotifyRequest {
  return { kind: "done", title: "标题", body: "正文", ...over };
}

describe("finalizeRequest", () => {
  // 缺省强度串了档，用户看到的呈现与事件严重性不符（error 看起来像普通提示）。
  it("内置 kind 补缺省强度：error 必须是 failure（出错通知显示成普通提示就白通知了）", () => {
    for (const [kind, severity] of KIND_SEVERITY_EXPECTED) {
      expect(finalizeRequest(requestOf({ kind }), 1).severity, kind).toBe(severity);
    }
    expect(KIND_SEVERITY_EXPECTED.map(([kind]) => kind).sort()).toEqual([...BUILTIN_KINDS].sort());
  });

  // 非法强度被当成合法值传给出口，对端会收到它不认识的档位。
  it("调用方显式给的强度优先；非法强度视同未提供，回落 kind 缺省", () => {
    expect(finalizeRequest(requestOf({ kind: "error", severity: "info" }), 1).severity).toBe(
      "info",
    );
    expect(
      finalizeRequest(requestOf({ kind: "error", severity: wire<NotifySeverity>("critical") }), 1)
        .severity,
    ).toBe("failure");
  });

  // 给外部 kind 补一个「中间档」，等于替调用方决定了它没说的语义。
  it("外部 kind 没有缺省强度：不写 severity 键，调用方说了才写", () => {
    expect("severity" in finalizeRequest(requestOf({ kind: "demo:report" }), 1)).toBe(false);
    expect(
      finalizeRequest(requestOf({ kind: "demo:report", severity: "warning" }), 1).severity,
    ).toBe("warning");
    expect(
      "severity" in
        finalizeRequest(requestOf({ kind: "demo:report", severity: wire<NotifySeverity>("x") }), 1),
    ).toBe(false);
  });

  // 在定稿层截正文会把系统通知的 256 上限强加给所有出口，用户的正文被提前砍掉。
  it("标题按 64 码点截断且不腰斩 emoji；正文原样透传（长度权威在各出口）", () => {
    expect(
      Array.from(finalizeRequest(requestOf({ title: "题".repeat(65) }), 1).title),
    ).toHaveLength(64);
    const emoji = "🙂".repeat(64);
    expect(finalizeRequest(requestOf({ title: emoji }), 1).title).toBe(emoji);
    const longBody = "文".repeat(5000);
    expect(finalizeRequest(requestOf({ body: longBody }), 1).body).toBe(longBody);
  });

  // ts 或 kind 被改写，历史与投递载荷就对不上号，webhook 的 {{kind}} 也会跟着错。
  it("定稿不改内容：kind 与 ts 原样进消息（webhook 的 {{kind}}、bark 的 levels[kind] 都靠它）", () => {
    const message = finalizeRequest(
      requestOf({ kind: "demo:report", title: "T", body: "B" }),
      1_700_000_000_000,
    );
    expect(message.kind).toBe("demo:report");
    expect(message.ts).toBe(1_700_000_000_000);
    expect(message.title).toBe("T");
    expect(message.body).toBe("B");
  });
});

packages/dsh-notifier/test/unit/channels.source:
/**
 * dsh-notifier channels 域 browser 出口 —— 跨端通知帧的构造。
 *
 * 帧是本域唯一的线协议产物（宿主 → 客户端），判据只有两条：
 *  - 铃声决议：页面在「只响不弹」时没有能发系统提示音的实体，只能自播；决议错了表现为
 *    用户开了声音却一声不响，或不该响的时候响；
 *  - 上限与可选键：正文进帧前必须按页面侧的上限截断，而 `severity` 缺席要**不写键**而不是写
 *    `undefined`——线协议两侧对「这个键在不在」的解释不同。
 * 帧出口用假实现收帧，本块不需要真推送设施。
 */
import { describe, expect, it } from "vitest";

import { sendBrowser } from "../../../src/server/channels/impl/browser/index.ts";
import type { BrowserTarget, NotifyFrame } from "../../../src/server/channels/impl/browser/type.ts";
import type { NotifyMessage } from "../../../src/server/channels/impl/deliver/type.ts";

function messageOf(over: Partial<NotifyMessage> = {}): NotifyMessage {
  return { title: "标题", body: "正文", kind: "done", ts: 1_700_000_000_000, ...over };
}

/** 收帧的假出口：帧是这条出口的唯一产物，收到即投递完成。 */
function collector(): {
  frames: NotifyFrame[];
  targetOf: (over?: Partial<BrowserTarget>) => BrowserTarget;
} {
  const frames: NotifyFrame[] = [];
  return {
    frames,
    targetOf: (over = {}) => ({
      type: "browser",
      popup: true,
      sound: true,
      whenVisible: false,
      emitFrame: (frame) => {
        frames.push(frame);
      },
      ...over,
    }),
  };
}

describe("sendBrowser", () => {
  // 只响不弹时页面里没有能发系统提示音的实体，判错就是「开了声音却一声不响」。
  it("铃声决议：false 静音，跟随系统按弹不弹分叉，显式音色走自播", () => {
    const { frames, targetOf } = collector();
    const first = sendBrowser(targetOf({ sound: false }), messageOf());
    sendBrowser(targetOf({ sound: true, popup: true }), messageOf());
    sendBrowser(targetOf({ sound: true, popup: false }), messageOf());
    sendBrowser(targetOf({ sound: "ding", popup: true }), messageOf());

    expect(frames.map((frame) => frame.sound)).toEqual([
      { mode: "silent" },
      { mode: "system" },
      { mode: "selfplay" },
      { mode: "selfplay", tone: "ding" },
    ]);
    expect(frames.map((frame) => frame.pop)).toEqual([true, true, false, true]);
    // 交给帧出口即完成：页面弹没弹不是宿主能证明的事，证据上限只能是 accepted。
    expect(first).toEqual({ status: "ok", stage: "accepted" });
  });

  // 写成 undefined 的 severity 键会被客户端读成「显式声明了空强度」；正文超限则显示被截断或整条丢弃。
  it("按页面侧上限截断标题与正文，severity 缺席就不写这个键，可见性随帧下发", () => {
    const { frames, targetOf } = collector();
    sendBrowser(targetOf(), messageOf({ title: "题".repeat(100), body: "文".repeat(3000) }));
    sendBrowser(targetOf({ whenVisible: true }), messageOf({ severity: "warning" }));

    expect(Array.from(frames[0]!.title)).toHaveLength(64);
    expect(Array.from(frames[0]!.body)).toHaveLength(2048);
    expect("severity" in frames[0]!).toBe(false);
    expect(frames[1]!.severity).toBe("warning");
    // 可见性只有页面知道，故随帧下发：渲染端回查配置会读到可能已经变过的那一份。
    expect(frames.map((frame) => frame.whenVisible)).toEqual([false, true]);
  });

  // 什么都不发也是一次投递，只是没有动作：发空帧会推进序号、进重放缓冲、并让页面认领主标签租约，
  // 而记成 ok 会让历史里多出一条没发生过的成功。判据必须把「出口自己的回答」钉死在结果上。
  it("弹窗与声音都关：不发帧，收成 skipped 而不是伪造一次投递成功", () => {
    const { frames, targetOf } = collector();
    const result = sendBrowser(targetOf({ popup: false, sound: false }), messageOf());

    // 成因经 code 带出去（与 system 出口同一个 code）：两个出口的「用户都关了」是同一件事
    expect(result).toEqual({
      status: "skipped",
      reason: { code: "reasonSkipConfig" },
    });
    expect(frames).toEqual([]);
  });
});

